begin;

insert into public.categories (id, slug, name, description, position) values
  ('10000000-0000-4000-a000-000000000001', 'epices', 'Épices & aromates', 'Poivres, graines et mélanges d''épices introuvables en grande surface, sélectionnés à la source.', 1),
  ('10000000-0000-4000-a000-000000000002', 'cereales', 'Farines & céréales', 'Fonio, attiéké, couscous de mil : les céréales anciennes et les semoules du continent.', 2),
  ('10000000-0000-4000-a000-000000000003', 'feuilles', 'Feuilles & fleurs séchées', 'Feuilles de ndolé, de manioc, fleurs d''hibiscus : séchées sur place pour garder leur goût.', 3),
  ('10000000-0000-4000-a000-000000000004', 'poissons', 'Poissons & fumés', 'Poissons séchés, fumés ou fermentés et crevettes séchées, les exhausteurs de goût de la cuisine africaine.', 4),
  ('10000000-0000-4000-a000-000000000005', 'huiles', 'Huiles & pâtes', 'Huile de palme rouge, pâte d''arachide, pulpe de noix de palme : la base des grandes sauces.', 5)
on conflict (id) do nothing;

insert into public.products (id, slug, name, category_id, short_description, description, origin_country, origin_region, producer, images, composition, allergens, usage_tips, conservation, tags, amazon_asin, is_active, featured, created_at) values
  ('20000000-0000-4000-a000-000000000001', 'poivre-de-penja', 'Poivre blanc de Penja', '10000000-0000-4000-a000-000000000001', 'Le poivre blanc des terres volcaniques du Cameroun, puissant et parfumé.', 'Cultivé au pied du mont Koupé, sur les sols volcaniques de la vallée du Moungo, le poivre de Penja est l''un des rares poivres africains à bénéficier d''une indication géographique protégée. Ses grains, trempés puis séchés au soleil, offrent un piquant franc et des notes boisées et musquées.

À moudre au dernier moment.', 'Cameroun', 'Penja, Littoral', null, array['/products/poivre-de-penja.webp']::text[], 'Poivre blanc en grains (Piper nigrum).', '{}'::text[], 'Sur les poissons braisés, le ndolé, les viandes grillées. Moudre en fin de cuisson pour garder tout son parfum.', 'À l''abri de la lumière et de l''humidité, dans un bocal fermé.', array['IGP', 'poivre']::text[], 'B000PBXHBS', true, true, '2026-01-01T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000002', 'soumbala', 'Soumbala (nététou)', '10000000-0000-4000-a000-000000000001', 'Graines de néré fermentées, le condiment de caractère du Sahel.', 'Le soumbala est obtenu par la fermentation des graines de néré, un arbre de la savane. Façonné en boules puis séché, il apporte aux sauces une profondeur et un goût umami incomparables. Au Sénégal on l''appelle nététou.

Une petite quantité suffit.', 'Burkina Faso', 'Région des Hauts-Bassins', null, array['/products/soumbala.webp']::text[], 'Graines de néré (Parkia biglobosa) fermentées, sel.', '{}'::text[], 'Écraser une boule dans le mafé, les sauces feuilles ou le riz gras, en début de cuisson.', 'Au sec, dans une boîte hermétique (l''odeur est puissante).', array['fermenté', 'umami']::text[], 'B0CQKHMT2Y', true, true, '2026-01-02T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000003', 'berbere', 'Berbéré d''Éthiopie', '10000000-0000-4000-a000-000000000001', 'Le mélange d''épices rouge et chaud de la cuisine éthiopienne.', 'Piment, fenugrec, gingembre, korarima, ajowan, clou de girofle : le berbéré est l''âme des wats éthiopiens. Notre mélange est torréfié puis moulu en petites quantités à Addis-Abeba.

Piquant et très aromatique.', 'Éthiopie', 'Addis-Abeba', null, array['/products/berbere.webp']::text[], 'Piment, paprika, fenugrec, gingembre, ail, korarima, ajowan, clou de girofle, sel.', '{}'::text[], 'Base du doro wat et du misir wat. Faire revenir dans le beurre épicé avant d''ajouter les oignons.', 'À l''abri de la lumière, dans un bocal fermé.', array['mélange', 'piquant']::text[], 'B079R281WV', true, false, '2026-01-03T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000004', 'yaji-suya', 'Yaji, épices à suya', '10000000-0000-4000-a000-000000000001', 'Le mélange arachide-piment des grillades de rue nigérianes.', 'Le yaji est le mélange qui enrobe le suya, la brochette grillée vendue au coin des rues de Lagos à Kano. Arachide torréfiée (kuli-kuli), piment, gingembre et épices : un enrobage croustillant et relevé.', 'Nigeria', 'Kano', null, array['/products/yaji-suya.webp']::text[], 'Arachide torréfiée, piment, gingembre, ail, oignon, bouillon d''épices, sel.', array['arachide']::text[], 'Frotter la viande avec le yaji avant de la griller, puis en saupoudrer à la sortie du feu.', 'Au sec, dans un bocal fermé.', array['grillade', 'piquant']::text[], 'B0CTTM79ZR', true, true, '2026-01-04T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000005', 'poivre-de-selim', 'Poivre de Selim (djar)', '10000000-0000-4000-a000-000000000001', 'Gousses fumées aux notes de résine et de muscade.', 'Le poivre de Selim, appelé djar au Sénégal ou kani en Côte d''Ivoire, se présente en longues gousses sombres. Légèrement fumées, elles parfument le café Touba, les bouillons et les marinades de notes résineuses, musquées et poivrées.', 'Sénégal', 'Casamance', null, array['/products/poivre-de-selim.webp']::text[], 'Gousses de Xylopia aethiopica.', '{}'::text[], 'Écraser les gousses et les infuser dans les bouillons, ou les moudre avec le café.', 'Au sec, à l''abri de la lumière.', array['cueillette', 'fumé']::text[], 'B07GFN2J77', true, false, '2026-01-05T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000006', 'fonio', 'Fonio précuit', '10000000-0000-4000-a000-000000000002', 'La plus ancienne céréale d''Afrique de l''Ouest, fine et légère.', 'Cultivé depuis des millénaires dans le Sahel, le fonio est une toute petite graine qui cuit en quelques minutes à la vapeur. Son goût léger, entre noisette et semoule, en fait l''accompagnement idéal des sauces.

Fonio décortiqué et précuit, prêt en 5 minutes.', 'Mali', 'Région de Kayes', null, array['/products/fonio.webp']::text[], 'Fonio (Digitaria exilis) décortiqué et précuit.', '{}'::text[], 'Cuire à la vapeur ou verser dans l''eau bouillante salée, couvrir 5 minutes puis égrainer à la fourchette.', 'Au sec, dans un contenant fermé.', array['céréale ancienne']::text[], 'B0C78LFHJS', true, true, '2026-01-06T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000007', 'attieke-sec', 'Attiéké déshydraté', '10000000-0000-4000-a000-000000000002', 'La semoule de manioc fermenté de Côte d''Ivoire, prête à réhydrater.', 'L''attiéké est une semoule de manioc fermenté, légèrement acidulée, qui accompagne le poisson braisé dans tous les maquis ivoiriens. Cette version séchée se conserve longtemps et retrouve sa texture en quelques minutes à la vapeur.', 'Côte d''Ivoire', 'Dabou', null, array['/products/attieke-sec.webp']::text[], 'Manioc fermenté, séché.', '{}'::text[], 'Humidifier, laisser gonfler 5 minutes puis réchauffer à la vapeur. Servir avec oignons, tomates et piment.', 'Au sec, dans un contenant fermé.', array['manioc', 'fermenté']::text[], 'B0CCLHXJFJ', true, false, '2026-01-07T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000008', 'couscous-de-mil', 'Couscous de mil (thiéré)', '10000000-0000-4000-a000-000000000002', 'Graines de mil roulées à la main, pour le thiakry et le thiéré.', 'Au Sénégal, le mil est roulé à la main en petites graines appelées araw ou thiéré, puis séché. Il sert autant aux plats salés qu''au thiakry, le dessert au lait caillé.', 'Sénégal', 'Kaolack', null, array['/products/couscous-de-mil.webp']::text[], 'Farine de mil.', '{}'::text[], 'Cuire à la vapeur deux fois en égrainant entre les deux cuissons.', 'Au sec, dans un contenant fermé.', array['mil']::text[], 'B0DWKQHXLN', true, false, '2026-01-08T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000009', 'feuilles-de-ndole', 'Feuilles de ndolé séchées', '10000000-0000-4000-a000-000000000003', 'Les feuilles amères indispensables au plat national camerounais.', 'Le ndolé (Vernonia) est une plante aux feuilles amères que l''on lave longuement avant de la cuisiner avec des arachides. Nos feuilles sont lavées, émincées et séchées au Cameroun : il suffit de les réhydrater.', 'Cameroun', 'Douala, Littoral', null, array['/products/feuilles-de-ndole.webp']::text[], 'Feuilles de Vernonia amygdalina lavées et séchées.', '{}'::text[], 'Réhydrater 30 minutes dans l''eau tiède, rincer deux fois puis presser avant de cuisiner.', 'Au sec, à l''abri de la lumière.', array['feuilles', 'Cameroun']::text[], 'B0FQQXJ23P', true, true, '2026-01-09T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000000a', 'feuilles-de-manioc', 'Feuilles de manioc pilées (pondu, ravitoto)', '10000000-0000-4000-a000-000000000003', 'Pondu séché, pour le plat mijoté emblématique des deux Congo.', 'Les jeunes feuilles de manioc sont pilées puis séchées pour préparer le pondu (ou saka-saka). Il mijote longuement avec de l''huile de palme, du poisson fumé et des aubergines.', 'RD Congo', 'Kinshasa', null, array['/products/feuilles-de-manioc.webp']::text[], 'Feuilles de manioc pilées et séchées.', '{}'::text[], 'Réhydrater, puis cuire au moins 1 h 30 à feu doux : les feuilles de manioc doivent être longuement cuites.', 'Au sec, dans un contenant fermé.', array['feuilles', 'Congo']::text[], 'B092379XP9', true, false, '2026-01-10T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000000b', 'fleurs-de-bissap', 'Fleurs de bissap', '10000000-0000-4000-a000-000000000003', 'Calices d''hibiscus rouge séchés, pour le jus de bissap.', 'Les calices d''hibiscus sabdariffa, séchés au soleil, donnent le bissap, la boisson rouge rubis servie dans toute l''Afrique de l''Ouest. Notre sélection vient de la région de Kaolack, réputée pour ses fleurs charnues et très colorées.', 'Sénégal', 'Kaolack', null, array['/products/fleurs-de-bissap.webp']::text[], 'Calices d''Hibiscus sabdariffa séchés.', '{}'::text[], 'Infuser à froid une nuit ou à chaud 10 minutes, filtrer, sucrer et parfumer à la menthe ou à la fleur d''oranger.', 'Au sec, à l''abri de la lumière.', array['boisson', 'hibiscus']::text[], 'B09LMHFX9T', true, true, '2026-01-11T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000000c', 'guedj', 'Guedj (poisson séché fermenté)', '10000000-0000-4000-a000-000000000004', 'Le secret du thiéboudienne : un poisson fermenté puis séché au soleil.', 'Le guedj est un poisson fermenté puis séché sur les plages de Joal et de Mbour. Utilisé en petite quantité, il donne au thiéboudienne et aux sauces leur goût profond et iodé.

Odeur puissante : c''est normal.', 'Sénégal', 'Joal-Fadiouth', null, array['/products/guedj.webp']::text[], 'Poisson fermenté et séché, sel.', array['poisson']::text[], 'Rincer, puis ajouter un morceau dans la sauce en début de cuisson.', 'Au sec, dans une boîte hermétique.', array['poisson', 'fermenté']::text[], 'B0DK3SVDJN', true, false, '2026-01-12T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000000d', 'crevettes-sechees', 'Crevettes séchées', '10000000-0000-4000-a000-000000000004', 'Petites crevettes séchées de l''estuaire du Wouri.', 'Séchées au soleil puis légèrement fumées, ces petites crevettes relèvent le ndolé, les sauces gombo et les soupes. On les utilise entières ou moulues.', 'Cameroun', 'Estuaire du Wouri', null, array['/products/crevettes-sechees.webp']::text[], 'Crevettes séchées, sel.', array['crustacés']::text[], 'Rincer rapidement, puis ajouter entières en fin de cuisson ou moudre dans la sauce.', 'Au sec, dans une boîte hermétique.', array['crustacés']::text[], 'B0BVGJQC39', true, false, '2026-01-13T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000000e', 'poisson-fume', 'Machoiron fumé', '10000000-0000-4000-a000-000000000004', 'Poisson-chat fumé au feu de bois, pour le pondu et les sauces.', 'Le machoiron est un poisson de rivière fumé lentement au feu de bois. Sa chair ferme et fumée parfume le pondu, les sauces graines et les légumes feuilles.', 'RD Congo', 'Fleuve Congo', 'Fumoirs de Maluku (fictif)', array['/products/poisson-fume.webp']::text[], 'Poisson-chat (Arius) fumé.', array['poisson']::text[], 'Tremper 15 minutes dans l''eau chaude, retirer les arêtes et émietter dans la sauce.', 'Au sec et au frais, dans une boîte hermétique.', array['fumé', 'poisson']::text[], null, false, false, '2026-01-14T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000000f', 'huile-de-palme-rouge', 'Huile de palme rouge', '10000000-0000-4000-a000-000000000005', 'Huile rouge non raffinée, pressée par un petit producteur ivoirien.', 'Pressée artisanalement à partir de noix de palme fraîches, cette huile rouge non raffinée garde sa couleur et son goût fruité. C''est la base du pondu, de la sauce graine et de nombreux plats d''Afrique centrale.

Issue d''une petite palmeraie familiale, sans déforestation.', 'Côte d''Ivoire', 'Région de la Mé', null, array['/products/huile-de-palme-rouge.webp']::text[], 'Huile de palme rouge non raffinée.', '{}'::text[], 'Chauffer doucement sans la faire fumer. Elle fige au frais : c''est normal.', 'À température ambiante, à l''abri de la lumière.', array['non raffinée']::text[], 'B0962X7DNX', true, false, '2026-01-15T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000010', 'pate-d-arachide', 'Pâte d''arachide', '10000000-0000-4000-a000-000000000005', 'Arachides grillées et broyées, rien d''autre. Pour le mafé.', 'Arachides de la région de Ségou, grillées puis broyées lentement à la meule. Sans sucre, sans sel ni huile ajoutée : exactement ce qu''il faut pour un vrai mafé.', 'Mali', 'Ségou', null, array['/products/pate-d-arachide.webp']::text[], 'Arachides grillées.', array['arachide']::text[], 'Délayer dans un peu de bouillon chaud avant de l''ajouter à la sauce.', 'À température ambiante. Remuer avant usage (l''huile remonte naturellement).', array['arachide']::text[], 'B07VX8JBYN', true, true, '2026-01-16T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000011', 'pulpe-de-noix-de-palme', 'Sauce graine (pulpe de noix de palme)', '10000000-0000-4000-a000-000000000005', 'La crème de noix de palme du poulet nyembwe et de la sauce graine.', 'Extraite des noix de palme cuites et pilées, cette pulpe orangée est la base du poulet nyembwe gabonais et de la sauce graine ivoirienne. Onctueuse et fruitée.', 'Gabon', 'Estuaire', null, array['/products/pulpe-de-noix-de-palme.webp']::text[], 'Pulpe de noix de palme, eau.', '{}'::text[], 'Diluer dans l''eau et faire réduire lentement avec la viande jusqu''à ce que l''huile remonte.', 'Avant ouverture : à température ambiante. Après ouverture : au frais, 5 jours.', array['palme']::text[], 'B07C1KX53F', true, false, '2026-01-17T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000012', 'graines-d-egusi', 'Egusi moulu (pistache africaine)', '10000000-0000-4000-a000-000000000001', 'Graines de courge africaine, à moudre pour épaissir les soupes nigérianes.', 'L''egusi est la graine d''une courge d''Afrique de l''Ouest. Moulue, elle épaissit et parfume la célèbre soupe egusi du Nigeria et du Ghana, avec un goût doux de noisette.

Graines décortiquées à la main, prêtes à moudre.', 'Nigeria', 'État d''Ogun', null, array['/products/graines-d-egusi.webp']::text[], 'Graines de courge egusi (Citrullus lanatus) décortiquées.', '{}'::text[], 'Moudre finement, délayer avec un peu d''eau puis cuire dans la sauce jusqu''à former des grumeaux moelleux.', 'Au sec, dans un contenant fermé.', array['graines', 'Nigeria']::text[], 'B0DLV721PS', true, true, '2026-01-18T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000013', 'gombo-seche', 'Gombo séché en poudre', '10000000-0000-4000-a000-000000000003', 'Gombo séché au soleil et moulu, pour la sauce gluante du tô.', 'Au Sahel, le gombo est coupé en rondelles, séché au soleil puis moulu. Cette poudre verte donne à la sauce gombo sa texture filante caractéristique, même loin de la saison des récoltes.', 'Burkina Faso', 'Plateau central', null, array['/products/gombo-seche.webp']::text[], 'Gombo (Abelmoschus esculentus) séché et moulu.', '{}'::text[], 'Verser en pluie dans la sauce frémissante en fouettant, puis cuire 5 minutes.', 'Au sec, à l''abri de la lumière.', array['gombo', 'Sahel']::text[], 'B0C66R4FWK', true, false, '2026-01-19T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000014', 'feuilles-de-moringa', 'Feuilles de moringa séchées', '10000000-0000-4000-a000-000000000003', 'Le nébédaye du Sénégal, pour le thiéré mbuum et les sauces feuilles.', 'Au Sénégal, les feuilles de moringa (nébédaye) parfument le thiéré mbuum, un couscous de mil aux feuilles et à l''arachide. Séchées à l''ombre, elles gardent leur couleur vert vif et leur goût herbacé.', 'Sénégal', 'Thiès', null, array['/products/feuilles-de-moringa.webp']::text[], 'Feuilles de moringa (Moringa oleifera) séchées.', '{}'::text[], 'Réhydrater quelques minutes puis ajouter dans la sauce ou le couscous en fin de cuisson.', 'Au sec, à l''abri de la lumière.', array['feuilles', 'Sénégal']::text[], 'B086JBQJ1J', true, false, '2026-01-20T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000015', 'feuilles-de-sorgho', 'Feuilles de sorgho rouge (waakye)', '10000000-0000-4000-a000-000000000003', 'Les feuilles qui donnent au waakye ghanéen sa couleur brun-rouge.', 'Au Ghana, le riz et les haricots du waakye cuisent avec des feuilles de sorgho rouge séchées, qui leur donnent leur couleur brun-rouge caractéristique et un léger parfum.', 'Ghana', 'Tamale', null, array['/products/feuilles-de-sorgho.webp']::text[], 'Feuilles et tiges de sorgho rouge séchées.', '{}'::text[], 'Rincer, ajouter à l''eau de cuisson du riz et des haricots, puis retirer avant de servir.', 'Au sec.', array['feuilles', 'Ghana']::text[], 'B0F922WGDC', true, false, '2026-01-21T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000016', 'feuilles-d-okok', 'Feuilles d''okok émincées', '10000000-0000-4000-a000-000000000003', 'Les feuilles de forêt de l''eru camerounais, finement émincées et séchées.', 'L''okok (ou eru) est une liane de la forêt camerounaise dont les feuilles, émincées très finement, se cuisinent avec de l''huile de palme, de la viande et du poisson fumé.', 'Cameroun', 'Sud-Ouest', 'Cueilleurs de Kumba (fictif)', array['/products/feuilles-d-okok.webp']::text[], 'Feuilles de Gnetum africanum émincées et séchées.', '{}'::text[], 'Réhydrater 15 minutes dans l''eau tiède avant de cuisiner.', 'Au sec, à l''abri de la lumière.', array['feuilles', 'forêt']::text[], null, false, false, '2026-01-22T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000017', 'odika', 'Odika (chocolat indigène)', '10000000-0000-4000-a000-000000000005', 'Pain d''amandes de mangue sauvage, l''ingrédient signature du Gabon.', 'L''odika, surnommé « chocolat indigène », est un pain sombre fait d''amandes de mangue sauvage grillées et pressées. Râpé dans les sauces, il leur donne une couleur brune, une texture onctueuse et un goût fumé très particulier.', 'Gabon', 'Ogooué-Ivindo', 'Forêt de Makokou (fictif)', array['/products/odika.webp']::text[], 'Amandes de mangue sauvage (Irvingia gabonensis) grillées et pressées.', array['fruits à coque']::text[], 'Râper ou chauffer légèrement pour ramollir, puis délayer dans la sauce en fin de cuisson.', 'Au sec et au frais, emballé.', array['Gabon', 'forêt']::text[], null, false, true, '2026-01-23T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000018', 'farine-de-teff', 'Farine de teff', '10000000-0000-4000-a000-000000000002', 'La minuscule céréale éthiopienne de l''injera.', 'Le teff est une céréale minuscule cultivée depuis des millénaires sur les hauts plateaux éthiopiens. Sa farine, fermentée quelques jours, donne l''injera, la grande galette alvéolée qui sert d''assiette et de couvert.', 'Éthiopie', 'Amhara', null, array['/products/farine-de-teff.webp']::text[], 'Farine complète de teff (Eragrostis tef).', '{}'::text[], 'Mélanger à l''eau et laisser fermenter 2 à 3 jours avant de cuire les injeras.', 'Au sec et au frais, dans un contenant fermé.', array['céréale ancienne', 'Éthiopie']::text[], 'B0C1TBB24S', true, true, '2026-01-24T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000019', 'poudre-de-baobab', 'Pain de singe (poudre de baobab)', '10000000-0000-4000-a000-000000000002', 'La pulpe acidulée du fruit du baobab, pour le bouye et le ngalakh.', 'Le fruit du baobab, appelé pain de singe, renferme une pulpe sèche et farineuse au goût acidulé. Au Sénégal, on en fait le jus de bouye et la crème du ngalakh, le dessert de Pâques.', 'Sénégal', 'Sine-Saloum', null, array['/products/poudre-de-baobab.webp']::text[], 'Pulpe de fruit du baobab (Adansonia digitata) tamisée.', '{}'::text[], 'Délayer dans l''eau froide ou le lait, filtrer si besoin et sucrer à votre goût.', 'Au sec, dans un contenant fermé.', array['baobab', 'Sénégal']::text[], 'B06Y3L4CP1', true, false, '2026-01-25T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000001a', 'farine-de-foufou', 'Farine de manioc pour foufou', '10000000-0000-4000-a000-000000000002', 'Pour préparer le fufu lisse et élastique en quelques minutes.', 'Mélange de farine de manioc et de plantain, cette farine permet de préparer un fufu lisse et élastique sans piler au mortier. Il accompagne les soupes du Ghana, du Nigeria et d''Afrique centrale.', 'Ghana', 'Kumasi', null, array['/products/farine-de-foufou.webp']::text[], 'Farine de manioc, farine de plantain.', '{}'::text[], 'Verser dans l''eau bouillante en remuant vigoureusement avec une spatule jusqu''à obtenir une pâte lisse.', 'Au sec, dans un contenant fermé.', array['manioc', 'plantain']::text[], 'B0DY1V2QVZ', true, false, '2026-01-26T00:00:00.000Z')
on conflict (id) do nothing;

