insert into public.recipes (id, slug, name, country_code, region, course, short_description, story, image, prep_minutes, cook_minutes, servings, difficulty, ingredients, steps, tips, tags, featured, is_published, created_at) values
  ('40000000-0000-4000-a000-000000000001', 'ndole', 'Ndolé aux crevettes', 'CM', 'Littoral, Douala', 'mijotes', 'Le plat national camerounais : feuilles amères, arachides fondantes et crevettes.', 'Né chez les Doualas, sur les rives du Wouri, le ndolé est devenu le plat des grandes occasions dans tout le Cameroun. On le prépare pour les mariages, les baptêmes et les dimanches en famille.

Sa magie tient à l''équilibre entre l''amertume des feuilles, patiemment lavées, et la douceur des arachides fraîches longuement mijotées.', '/recipes/ndole.webp', 40, 75, 6, 3, '[{"quantity":200,"unit":"g","name":"feuilles de ndolé séchées","productSlug":"feuilles-de-ndole"},{"quantity":500,"unit":"g","name":"arachides crues décortiquées","productSlug":null},{"quantity":500,"unit":"g","name":"crevettes fraîches décortiquées","productSlug":null},{"quantity":50,"unit":"g","name":"crevettes séchées","productSlug":"crevettes-sechees"},{"quantity":400,"unit":"g","name":"bœuf à braiser en cubes","productSlug":null},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":3,"unit":"gousses","name":"ail","productSlug":null},{"quantity":1,"unit":"morceau","name":"gingembre frais (3 cm)","productSlug":null},{"quantity":10,"unit":"cl","name":"huile d''arachide","productSlug":null},{"quantity":null,"unit":null,"name":"poivre blanc de Penja","productSlug":"poivre-de-penja"},{"quantity":null,"unit":null,"name":"sel","productSlug":null}]'::jsonb, '[{"text":"Réhydrater les feuilles de ndolé 30 minutes dans l''eau tiède, puis les rincer deux fois et les presser fortement pour retirer l''amertume.","image":null},{"text":"Faire tremper les arachides 15 minutes dans l''eau chaude, retirer les peaux, puis les cuire 20 minutes et les mixer en une pâte fine avec un peu d''eau de cuisson.","image":null},{"text":"Faire revenir le bœuf dans une cocotte avec un oignon émincé, l''ail et le gingembre mixés. Couvrir d''eau et laisser mijoter 40 minutes.","image":null},{"text":"Ajouter la pâte d''arachide et les crevettes séchées, puis cuire 15 minutes à feu doux en remuant souvent pour que rien n''attache.","image":null},{"text":"Incorporer les feuilles de ndolé et laisser mijoter encore 15 minutes. Saler et poivrer généreusement au poivre de Penja.","image":null},{"text":"Dans une poêle, faire dorer les crevettes fraîches avec le second oignon émincé dans l''huile, puis les verser sur le ndolé au moment de servir.","image":null}]'::jsonb, array['Servez avec du plantain mûr frit (miondo ou bâton de manioc au Cameroun).', 'Plus les feuilles sont rincées, moins le ndolé est amer : goûtez-les avant de les cuire.']::text[], array['fête', 'arachide']::text[], true, true, '2026-02-01T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000002', 'mafe', 'Mafé de bœuf', 'ML', 'Bamako', 'mijotes', 'Bœuf fondant dans une sauce onctueuse à la pâte d''arachide.', 'Le mafé, ou tigadèguèna (« sauce d''arachide » en bambara), vient des Mandingues du Mali. Il s''est répandu dans toute l''Afrique de l''Ouest, chaque pays y ajoutant sa touche.

C''est le plat du quotidien par excellence : une grande marmite qui mijote pendant que la famille se réunit.', '/recipes/mafe.webp', 20, 90, 6, 1, '[{"quantity":800,"unit":"g","name":"bœuf à braiser en morceaux","productSlug":null},{"quantity":250,"unit":"g","name":"pâte d''arachide pure","productSlug":"pate-d-arachide"},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":3,"unit":"c. à soupe","name":"concentré de tomate","productSlug":null},{"quantity":2,"unit":null,"name":"tomates","productSlug":null},{"quantity":3,"unit":null,"name":"carottes","productSlug":null},{"quantity":2,"unit":null,"name":"patates douces","productSlug":null},{"quantity":0.25,"unit":null,"name":"chou blanc","productSlug":null},{"quantity":1,"unit":"boule","name":"soumbala","productSlug":"soumbala"},{"quantity":1,"unit":null,"name":"piment antillais entier","productSlug":null},{"quantity":4,"unit":"c. à soupe","name":"huile","productSlug":null},{"quantity":null,"unit":null,"name":"sel et poivre","productSlug":null}]'::jsonb, '[{"text":"Faire dorer la viande dans l''huile, puis ajouter les oignons émincés et laisser fondre 5 minutes.","image":null},{"text":"Ajouter le concentré de tomate, les tomates concassées et le soumbala écrasé. Couvrir d''un litre d''eau et laisser cuire 30 minutes.","image":null},{"text":"Délayer la pâte d''arachide dans une louche de bouillon chaud et l''incorporer à la sauce.","image":null},{"text":"Ajouter les carottes, les patates douces, le chou et le piment entier (sans le percer). Cuire 45 minutes à feu doux en remuant régulièrement.","image":null},{"text":"Quand l''huile remonte à la surface, le mafé est prêt. Rectifier l''assaisonnement.","image":null}]'::jsonb, array['Servez avec du riz blanc ou du fonio.', 'Le mafé est encore meilleur réchauffé le lendemain.']::text[], array['arachide', 'familial']::text[], true, true, '2026-02-02T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000003', 'pondu', 'Pondu au poisson fumé', 'CD', 'Kinshasa', 'mijotes', 'Feuilles de manioc mijotées à l''huile de palme et au poisson fumé.', 'Le pondu, ou saka-saka, est le légume-feuille des deux rives du fleuve Congo. Les feuilles de manioc, pilées au mortier, mijotent longuement jusqu''à devenir fondantes.

À Kinshasa, on le sert avec de la chikwangue ou du fufu, et chaque famille a sa recette : avec du poisson fumé, de la viande ou simplement des aubergines.', '/recipes/pondu.webp', 20, 120, 4, 2, '[{"quantity":200,"unit":"g","name":"feuilles de manioc pilées","productSlug":"feuilles-de-manioc"},{"quantity":200,"unit":"g","name":"machoiron fumé","productSlug":"poisson-fume"},{"quantity":10,"unit":"cl","name":"huile de palme rouge","productSlug":"huile-de-palme-rouge"},{"quantity":2,"unit":null,"name":"aubergines africaines (ou 1 aubergine)","productSlug":null},{"quantity":1,"unit":null,"name":"oignon","productSlug":null},{"quantity":2,"unit":"gousses","name":"ail","productSlug":null},{"quantity":1,"unit":null,"name":"poivron vert","productSlug":null},{"quantity":1,"unit":null,"name":"piment","productSlug":null},{"quantity":null,"unit":null,"name":"sel","productSlug":null}]'::jsonb, '[{"text":"Réhydrater les feuilles de manioc dans de l''eau tiède 20 minutes, puis les porter à ébullition dans une grande casserole d''eau.","image":null},{"text":"Laisser cuire à feu doux 1 heure en ajoutant de l''eau si nécessaire : les feuilles de manioc doivent toujours être bien cuites.","image":null},{"text":"Pendant ce temps, faire tremper le poisson fumé dans l''eau chaude, retirer peau et arêtes et l''émietter.","image":null},{"text":"Ajouter l''oignon, l''ail, le poivron et les aubergines coupés en morceaux, puis le poisson. Poursuivre la cuisson 40 minutes.","image":null},{"text":"Verser l''huile de palme rouge, saler, ajouter le piment et laisser mijoter encore 15 minutes à découvert.","image":null}]'::jsonb, array['Accompagnez de chikwangue, de fufu ou de riz.', 'Une cuillère de pâte d''arachide rend le pondu plus onctueux.']::text[], array['feuilles', 'fumé']::text[], false, true, '2026-02-03T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000004', 'doro-wat', 'Doro wat', 'ET', 'Hauts plateaux', 'mijotes', 'Le ragoût de poulet au berbéré et aux œufs, plat de fête éthiopien.', 'Le doro wat est le plat de fête de l''Éthiopie, servi à Noël et à Pâques après les longues périodes de jeûne. Sa préparation commence par une montagne d''oignons cuits à sec pendant près d''une heure.

Il se mange à la main, avec l''injera, la grande crêpe acidulée au teff.', '/recipes/doro-wat.webp', 30, 100, 4, 2, '[{"quantity":8,"unit":null,"name":"cuisses de poulet sans peau","productSlug":null},{"quantity":1,"unit":"kg","name":"oignons rouges","productSlug":null},{"quantity":4,"unit":"c. à soupe","name":"berbéré","productSlug":"berbere"},{"quantity":80,"unit":"g","name":"beurre","productSlug":null},{"quantity":4,"unit":"gousses","name":"ail","productSlug":null},{"quantity":1,"unit":"morceau","name":"gingembre frais (4 cm)","productSlug":null},{"quantity":4,"unit":null,"name":"œufs durs","productSlug":null},{"quantity":1,"unit":null,"name":"citron","productSlug":null},{"quantity":null,"unit":null,"name":"sel","productSlug":null}]'::jsonb, '[{"text":"Frotter le poulet avec le jus du citron et du sel, et laisser reposer 20 minutes.","image":null},{"text":"Hacher très finement les oignons et les cuire à sec, sans matière grasse, dans une cocotte à feu doux pendant 40 minutes en remuant souvent : ils doivent devenir une compote brune.","image":null},{"text":"Ajouter le beurre, l''ail et le gingembre râpés, puis le berbéré. Cuire 10 minutes en remuant.","image":null},{"text":"Ajouter le poulet et 40 cl d''eau. Laisser mijoter à couvert 45 minutes.","image":null},{"text":"Entailler les œufs durs écalés et les ajouter dans la sauce 10 minutes avant la fin de la cuisson.","image":null}]'::jsonb, array['Servez avec de l''injera, ou à défaut du riz.', 'Pour une version authentique, remplacez le beurre par du niter kibbeh (beurre clarifié épicé).']::text[], array['fête', 'épicé']::text[], true, true, '2026-02-04T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000005', 'poulet-nyembwe', 'Poulet nyembwe', 'GA', 'Libreville', 'mijotes', 'Poulet mijoté dans la crème de noix de palme, le plat national gabonais.', 'Le poulet nyembwe est le plat national du Gabon. La pulpe de noix de palme, longuement réduite, enrobe la viande d''une sauce orangée, onctueuse et fruitée.

On le sert avec du riz ou du manioc, souvent le dimanche.', '/recipes/poulet-nyembwe.webp', 20, 60, 4, 1, '[{"quantity":1,"unit":null,"name":"poulet découpé en morceaux","productSlug":null},{"quantity":400,"unit":"g","name":"pulpe de noix de palme","productSlug":"pulpe-de-noix-de-palme"},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":3,"unit":"gousses","name":"ail","productSlug":null},{"quantity":1,"unit":null,"name":"piment","productSlug":null},{"quantity":2,"unit":"c. à soupe","name":"huile","productSlug":null},{"quantity":null,"unit":null,"name":"sel et poivre","productSlug":null}]'::jsonb, '[{"text":"Faire dorer les morceaux de poulet dans l''huile, puis ajouter les oignons émincés et l''ail.","image":null},{"text":"Diluer la pulpe de noix de palme dans 50 cl d''eau chaude et la verser sur le poulet.","image":null},{"text":"Ajouter le piment entier, saler, poivrer et laisser mijoter à feu doux 45 minutes, jusqu''à ce que la sauce épaississe et que l''huile rouge remonte.","image":null}]'::jsonb, array['Servez avec du riz blanc ou des bâtons de manioc.']::text[], array['palme']::text[], false, true, '2026-02-05T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000006', 'poulet-yassa', 'Poulet yassa', 'SN', 'Casamance', 'grillades', 'Poulet grillé, puis mijoté dans une montagne d''oignons au citron.', 'Originaire de Casamance, au sud du Sénégal, le yassa est devenu l''un des plats les plus aimés du pays. Le poulet mariné est d''abord grillé au charbon, puis mijote dans les oignons fondus au citron et à la moutarde.

Acidulé, doux et fumé à la fois.', '/recipes/poulet-yassa.webp', 30, 60, 4, 1, '[{"quantity":1,"unit":null,"name":"poulet découpé en morceaux","productSlug":null},{"quantity":6,"unit":null,"name":"gros oignons","productSlug":null},{"quantity":4,"unit":null,"name":"citrons verts","productSlug":null},{"quantity":2,"unit":"c. à soupe","name":"moutarde","productSlug":null},{"quantity":3,"unit":"gousses","name":"ail","productSlug":null},{"quantity":2,"unit":"gousses","name":"poivre de Selim","productSlug":"poivre-de-selim"},{"quantity":1,"unit":null,"name":"piment","productSlug":null},{"quantity":10,"unit":"cl","name":"huile","productSlug":null},{"quantity":null,"unit":null,"name":"olives vertes","productSlug":null},{"quantity":null,"unit":null,"name":"sel et poivre","productSlug":null}]'::jsonb, '[{"text":"Émincer les oignons. Les mélanger avec le jus des citrons, la moutarde, l''ail écrasé, le poivre de Selim moulu, l''huile, du sel et du poivre.","image":null},{"text":"Ajouter le poulet et laisser mariner au moins 4 heures (idéalement une nuit) au frais.","image":null},{"text":"Égoutter le poulet et le griller au barbecue ou au four très chaud jusqu''à ce qu''il soit bien doré.","image":null},{"text":"Faire fondre les oignons de la marinade à feu moyen 20 minutes, puis ajouter le reste de la marinade et un verre d''eau.","image":null},{"text":"Ajouter le poulet grillé, le piment entier et les olives, et laisser mijoter 20 minutes.","image":null}]'::jsonb, array['Servez avec du riz blanc.', 'Le poisson (dorade, capitaine) se prépare de la même façon.']::text[], array['citron', 'grillé']::text[], true, true, '2026-02-06T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000007', 'suya', 'Suya de bœuf', 'NG', 'Kano', 'grillades', 'Brochettes de bœuf grillées, enrobées d''épices yaji à l''arachide.', 'Le suya est la grillade de rue du Nigeria. Venue des Haoussas du nord, elle se vend le soir, au bord des routes, sur des braises rougeoyantes.

La viande, taillée très fine, est enrobée de yaji, un mélange d''arachide et de piment qui caramélise sur le feu.', '/recipes/suya.webp', 25, 15, 4, 1, '[{"quantity":600,"unit":"g","name":"rumsteck ou faux-filet","productSlug":null},{"quantity":60,"unit":"g","name":"yaji, épices à suya","productSlug":"yaji-suya"},{"quantity":3,"unit":"c. à soupe","name":"huile d''arachide","productSlug":null},{"quantity":1,"unit":null,"name":"oignon rouge","productSlug":null},{"quantity":2,"unit":null,"name":"tomates","productSlug":null},{"quantity":null,"unit":null,"name":"sel","productSlug":null}]'::jsonb, '[{"text":"Tailler la viande en tranches très fines, puis l''enfiler en accordéon sur des brochettes.","image":null},{"text":"Badigeonner d''huile, saler, puis enrober généreusement de yaji. Laisser reposer 30 minutes.","image":null},{"text":"Griller sur des braises bien chaudes ou sous le gril du four, 4 à 5 minutes de chaque côté.","image":null},{"text":"Servir saupoudré d''un peu de yaji, avec l''oignon rouge émincé et les tomates en rondelles.","image":null}]'::jsonb, array['Le poulet se prépare aussi en suya.', 'Allergène : le yaji contient de l''arachide.']::text[], array['street food', 'piquant']::text[], true, true, '2026-02-07T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000008', 'poisson-braise-attieke', 'Poisson braisé et attiéké', 'CI', 'Abidjan', 'grillades', 'Le classique des maquis d''Abidjan : poisson grillé, attiéké et sauce crue.', 'Le poisson braisé servi avec de l''attiéké est le plat emblématique des maquis, ces restaurants en plein air d''Abidjan. Le poisson, mariné aux épices, est grillé au charbon et servi avec une sauce crue de tomates, d''oignons et de piment.

On le mange avec les doigts, entre amis.', '/recipes/poisson-braise-attieke.webp', 25, 25, 4, 2, '[{"quantity":2,"unit":null,"name":"dorades ou bars vidés (500 g chacun)","productSlug":null},{"quantity":400,"unit":"g","name":"attiéké déshydraté","productSlug":"attieke-sec"},{"quantity":3,"unit":null,"name":"tomates","productSlug":null},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":1,"unit":null,"name":"poivron vert","productSlug":null},{"quantity":1,"unit":"morceau","name":"gingembre frais (3 cm)","productSlug":null},{"quantity":3,"unit":"gousses","name":"ail","productSlug":null},{"quantity":1,"unit":null,"name":"piment frais","productSlug":null},{"quantity":2,"unit":null,"name":"citrons verts","productSlug":null},{"quantity":6,"unit":"c. à soupe","name":"huile","productSlug":null},{"quantity":null,"unit":null,"name":"sel et poivre de Penja","productSlug":"poivre-de-penja"}]'::jsonb, '[{"text":"Mixer l''ail, le gingembre, la moitié du piment, un demi-oignon, 3 cuillères d''huile, du sel et du poivre. Entailler les poissons et les enduire de cette marinade. Laisser reposer 30 minutes.","image":null},{"text":"Pour la sauce crue, couper finement les tomates, le reste des oignons, le poivron et le piment. Assaisonner de citron, de sel et d''un filet d''huile.","image":null},{"text":"Griller les poissons sur des braises ou au four à 220 °C, 10 à 12 minutes de chaque côté.","image":null},{"text":"Humidifier l''attiéké avec un peu d''eau salée, le laisser gonfler 5 minutes, puis le réchauffer à la vapeur 10 minutes.","image":null},{"text":"Servir le poisson avec l''attiéké et la sauce crue par-dessus.","image":null}]'::jsonb, array['Ajoutez de l''alloco (bananes plantains frites) pour un repas complet.']::text[], array['maquis', 'poisson']::text[], false, true, '2026-02-08T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000009', 'thieboudienne', 'Thiéboudienne', 'SN', 'Saint-Louis', 'riz-cereales', 'Le riz au poisson du Sénégal, cuit dans le bouillon de légumes.', 'Le thiéboudienne (« riz au poisson » en wolof) serait né à Saint-Louis, au XIXᵉ siècle, dans la cuisine de Penda Mbaye. Il est aujourd''hui inscrit au patrimoine culturel immatériel de l''UNESCO.

Le poisson farci au persil, les légumes et le riz cuisent successivement dans le même bouillon rouge, relevé de guedj et de yeet.', '/recipes/thieboudienne.webp', 45, 90, 6, 3, '[{"quantity":1.5,"unit":"kg","name":"poisson ferme (thiof, mérou ou dorade) en tranches","productSlug":null},{"quantity":600,"unit":"g","name":"riz brisé","productSlug":null},{"quantity":1,"unit":null,"name":"botte de persil","productSlug":null},{"quantity":4,"unit":"gousses","name":"ail","productSlug":null},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":70,"unit":"g","name":"concentré de tomate","productSlug":null},{"quantity":50,"unit":"g","name":"guedj","productSlug":"guedj"},{"quantity":1,"unit":"boule","name":"nététou (soumbala)","productSlug":"soumbala"},{"quantity":2,"unit":null,"name":"carottes","productSlug":null},{"quantity":1,"unit":null,"name":"manioc","productSlug":null},{"quantity":1,"unit":null,"name":"aubergine","productSlug":null},{"quantity":0.25,"unit":null,"name":"chou blanc","productSlug":null},{"quantity":1,"unit":null,"name":"patate douce","productSlug":null},{"quantity":4,"unit":null,"name":"gombos","productSlug":null},{"quantity":15,"unit":"cl","name":"huile","productSlug":null},{"quantity":1,"unit":null,"name":"piment","productSlug":null},{"quantity":null,"unit":null,"name":"sel et poivre","productSlug":null}]'::jsonb, '[{"text":"Mixer le persil, l''ail, le piment, du sel et du poivre. Entailler les tranches de poisson et les farcir de ce mélange (le « roff »).","image":null},{"text":"Faire dorer le poisson dans l''huile chaude, puis le réserver.","image":null},{"text":"Dans la même huile, faire revenir les oignons, ajouter le concentré de tomate dilué, le guedj et le nététou. Cuire 10 minutes.","image":null},{"text":"Verser 2 litres d''eau, ajouter les légumes coupés en gros morceaux et le poisson. Cuire 40 minutes en retirant les légumes et le poisson au fur et à mesure qu''ils sont cuits.","image":null},{"text":"Laver le riz, le cuire à la vapeur 15 minutes, puis le verser dans le bouillon (il doit juste le couvrir). Cuire à couvert et à feu doux 25 minutes.","image":null},{"text":"Servir le riz dans un grand plat, avec le poisson et les légumes par-dessus. Le riz croustillant du fond (le « xoon ») est la partie la plus recherchée.","image":null}]'::jsonb, array['Pressez un citron vert sur l''assiette au moment de servir.', 'Le yeet (mollusque séché) apporte un goût encore plus authentique.']::text[], array['UNESCO', 'poisson', 'fête']::text[], true, true, '2026-02-09T00:00:00.000Z'),
  ('40000000-0000-4000-a000-00000000000a', 'fonio-aux-legumes', 'Fonio aux légumes et sauce arachide', 'BF', 'Bobo-Dioulasso', 'riz-cereales', 'La céréale ancienne du Sahel, légère, avec une sauce aux légumes.', 'Au Burkina Faso et au Mali, le fonio est la céréale des jours de fête et des hôtes de marque. On dit qu''il ne fait jamais honte à celui qui le cuisine, car il est toujours réussi.

Cuit à la vapeur en quelques minutes, il accompagne ici une sauce aux légumes relevée de soumbala.', '/recipes/fonio-aux-legumes.webp', 20, 35, 4, 1, '[{"quantity":300,"unit":"g","name":"fonio précuit","productSlug":"fonio"},{"quantity":2,"unit":null,"name":"courgettes","productSlug":null},{"quantity":2,"unit":null,"name":"carottes","productSlug":null},{"quantity":1,"unit":null,"name":"oignon","productSlug":null},{"quantity":2,"unit":null,"name":"tomates","productSlug":null},{"quantity":100,"unit":"g","name":"pâte d''arachide","productSlug":"pate-d-arachide"},{"quantity":1,"unit":"boule","name":"soumbala","productSlug":"soumbala"},{"quantity":3,"unit":"c. à soupe","name":"huile","productSlug":null},{"quantity":null,"unit":null,"name":"sel et piment","productSlug":null}]'::jsonb, '[{"text":"Faire revenir l''oignon émincé dans l''huile, ajouter les tomates concassées et le soumbala écrasé.","image":null},{"text":"Ajouter les carottes et les courgettes en dés, couvrir d''eau et cuire 20 minutes.","image":null},{"text":"Délayer la pâte d''arachide dans un peu de bouillon, l''incorporer et laisser épaissir 10 minutes.","image":null},{"text":"Porter 45 cl d''eau salée à ébullition, verser le fonio, couvrir hors du feu 5 minutes puis égrainer à la fourchette.","image":null},{"text":"Servir le fonio avec la sauce aux légumes.","image":null}]'::jsonb, array['Le fonio se prépare aussi en salade froide, comme un taboulé.']::text[], array['végétarien', 'céréale ancienne']::text[], false, true, '2026-02-10T00:00:00.000Z'),
  ('40000000-0000-4000-a000-00000000000b', 'alloco', 'Alloco', 'CI', 'Abidjan', 'accompagnements', 'Bananes plantains mûres frites, dorées et fondantes.', 'L''alloco tire son nom d''Allocodrome, le quartier de Cocody à Abidjan où les vendeuses frient les plantains le soir venu. Il accompagne le poisson braisé, le poulet ou se mange tel quel avec une sauce pimentée.', '/recipes/alloco.webp', 10, 15, 4, 1, '[{"quantity":4,"unit":null,"name":"bananes plantains bien mûres (peau noire)","productSlug":null},{"quantity":50,"unit":"cl","name":"huile de friture","productSlug":null},{"quantity":1,"unit":null,"name":"oignon","productSlug":null},{"quantity":1,"unit":null,"name":"piment","productSlug":null},{"quantity":null,"unit":null,"name":"sel","productSlug":null}]'::jsonb, '[{"text":"Éplucher les plantains et les couper en rondelles épaisses ou en biais.","image":null},{"text":"Saler légèrement et frire dans l''huile chaude (170 °C) 4 à 5 minutes, jusqu''à ce qu''ils soient bien dorés.","image":null},{"text":"Égoutter sur du papier absorbant et servir avec l''oignon et le piment hachés.","image":null}]'::jsonb, array['Plus le plantain est mûr, plus l''alloco est sucré et fondant.']::text[], array['végétarien', 'street food']::text[], false, true, '2026-02-11T00:00:00.000Z'),
  ('40000000-0000-4000-a000-00000000000c', 'kelewele', 'Kelewele', 'GH', 'Accra', 'accompagnements', 'Dés de plantain épicés au gingembre et au piment, frits.', 'Le kelewele est l''en-cas du soir à Accra. Les dés de plantain mûr sont marinés au gingembre, au piment et aux épices avant d''être frits, puis servis avec des arachides grillées.', '/recipes/kelewele.webp', 15, 15, 4, 1, '[{"quantity":4,"unit":null,"name":"bananes plantains mûres","productSlug":null},{"quantity":1,"unit":"morceau","name":"gingembre frais (5 cm)","productSlug":null},{"quantity":1,"unit":null,"name":"piment","productSlug":null},{"quantity":0.5,"unit":null,"name":"oignon","productSlug":null},{"quantity":2,"unit":"gousses","name":"poivre de Selim","productSlug":"poivre-de-selim"},{"quantity":50,"unit":"cl","name":"huile de friture","productSlug":null},{"quantity":null,"unit":null,"name":"sel","productSlug":null}]'::jsonb, '[{"text":"Mixer le gingembre, le piment, l''oignon, le poivre de Selim et une pincée de sel avec 2 cuillères d''eau.","image":null},{"text":"Couper les plantains en dés et les enrober de cette pâte. Laisser reposer 15 minutes.","image":null},{"text":"Frire les dés dans l''huile chaude jusqu''à ce qu''ils soient caramélisés, puis égoutter.","image":null}]'::jsonb, array['Servez avec des arachides grillées.']::text[], array['végétarien', 'épicé']::text[], false, true, '2026-02-12T00:00:00.000Z'),
  ('40000000-0000-4000-a000-00000000000d', 'jus-de-bissap', 'Jus de bissap', 'SN', 'Dakar', 'douceurs', 'La boisson rouge rubis à la fleur d''hibiscus, menthe et fleur d''oranger.', 'Le bissap est la boisson de l''hospitalité au Sénégal : on l''offre aux invités, on le sert aux mariages et à la rupture du jeûne pendant le ramadan.

Sa couleur rubis et son goût acidulé en font la boisson la plus populaire d''Afrique de l''Ouest.', '/recipes/jus-de-bissap.webp', 15, 10, 8, 1, '[{"quantity":100,"unit":"g","name":"fleurs de bissap","productSlug":"fleurs-de-bissap"},{"quantity":2,"unit":"l","name":"eau","productSlug":null},{"quantity":200,"unit":"g","name":"sucre","productSlug":null},{"quantity":1,"unit":null,"name":"botte de menthe fraîche","productSlug":null},{"quantity":1,"unit":"c. à soupe","name":"eau de fleur d''oranger","productSlug":null},{"quantity":1,"unit":"sachet","name":"sucre vanillé","productSlug":null}]'::jsonb, '[{"text":"Rincer rapidement les fleurs de bissap à l''eau froide.","image":null},{"text":"Porter l''eau à ébullition, y plonger les fleurs et la menthe, puis laisser infuser 10 minutes hors du feu.","image":null},{"text":"Filtrer, ajouter le sucre, le sucre vanillé et la fleur d''oranger, et bien mélanger.","image":null},{"text":"Laisser refroidir, puis servir très frais.","image":null}]'::jsonb, array['Infusion à froid : laissez les fleurs une nuit dans l''eau froide, le goût est plus fruité.', 'Les fleurs infusées peuvent servir une seconde fois.']::text[], array['boisson', 'sans cuisson']::text[], true, true, '2026-02-13T00:00:00.000Z'),
  ('40000000-0000-4000-a000-00000000000e', 'thiakry', 'Thiakry', 'SN', 'Dakar', 'douceurs', 'Couscous de mil au lait caillé, vanille et muscade.', 'Le thiakry (ou dégué au Burkina Faso) est le dessert frais des fêtes sénégalaises, notamment à la Tabaski. Les graines de mil cuites à la vapeur sont mélangées à un lait caillé sucré et parfumé.', '/recipes/thiakry.webp', 15, 30, 6, 1, '[{"quantity":250,"unit":"g","name":"couscous de mil","productSlug":"couscous-de-mil"},{"quantity":1,"unit":"l","name":"lait fermenté (ou yaourt nature)","productSlug":null},{"quantity":200,"unit":"g","name":"lait concentré sucré","productSlug":null},{"quantity":80,"unit":"g","name":"sucre","productSlug":null},{"quantity":1,"unit":"sachet","name":"sucre vanillé","productSlug":null},{"quantity":null,"unit":null,"name":"noix de muscade râpée","productSlug":null},{"quantity":null,"unit":null,"name":"raisins secs (facultatif)","productSlug":null}]'::jsonb, '[{"text":"Humidifier le couscous de mil et le cuire à la vapeur 15 minutes. L''égrainer, l''humidifier à nouveau et le recuire 15 minutes.","image":null},{"text":"Laisser refroidir complètement en égrainant à la main.","image":null},{"text":"Fouetter le lait fermenté avec le lait concentré, le sucre, le sucre vanillé et la muscade.","image":null},{"text":"Mélanger avec le mil, ajouter les raisins et servir bien frais.","image":null}]'::jsonb, array['Préparé la veille, il est encore meilleur.']::text[], array['dessert', 'fête']::text[], false, true, '2026-02-14T00:00:00.000Z'),
  ('40000000-0000-4000-a000-00000000000f', 'riz-jollof', 'Riz jollof', 'NG', 'Lagos', 'riz-cereales', 'Riz cuit dans une sauce tomate pimentée, fumé au fond de la marmite.', 'Le riz jollof tiendrait son nom de l''ancien royaume wolof (Djolof), au Sénégal, où serait né l''ancêtre du plat, le thiéboudienne. Il a voyagé le long de la côte et s''est imposé au Nigeria et au Ghana, qui se disputent aujourd''hui, avec beaucoup d''humour, le titre du « meilleur jollof ».

Au Nigeria, c''est le plat incontournable des « parties » : mariages, anniversaires et fêtes de quartier. Les connaisseurs réclament le riz légèrement fumé qui accroche au fond de la marmite, le fameux « party jollof ».', '/recipes/riz-jollof.webp', 25, 60, 6, 2, '[{"quantity":500,"unit":"g","name":"riz long grain étuvé","productSlug":null},{"quantity":4,"unit":null,"name":"tomates bien mûres","productSlug":null},{"quantity":2,"unit":null,"name":"poivrons rouges","productSlug":null},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":1,"unit":null,"name":"piment scotch bonnet","productSlug":null},{"quantity":70,"unit":"g","name":"concentré de tomate","productSlug":null},{"quantity":10,"unit":"cl","name":"huile végétale","productSlug":null},{"quantity":75,"unit":"cl","name":"bouillon de volaille","productSlug":null},{"quantity":2,"unit":"c. à café","name":"curry en poudre","productSlug":null},{"quantity":1,"unit":"c. à café","name":"thym séché","productSlug":null},{"quantity":2,"unit":null,"name":"feuilles de laurier","productSlug":null},{"quantity":null,"unit":null,"name":"mélange yaji (suya) pour relever","productSlug":"yaji-suya"}]'::jsonb, '[{"text":"Mixer les tomates, les poivrons, un oignon et le piment en une purée lisse. La faire réduire 15 minutes dans une casserole jusqu''à ce qu''elle épaississe.","image":null},{"text":"Dans une grande marmite, faire chauffer l''huile et y dorer le second oignon émincé. Ajouter le concentré de tomate et le faire frire 5 minutes en remuant, jusqu''à ce qu''il fonce légèrement.","image":null},{"text":"Verser la purée réduite, le curry, le thym, le laurier et une pincée de yaji. Laisser frémir 10 minutes : l''huile doit remonter à la surface.","image":null},{"text":"Rincer le riz jusqu''à ce que l''eau soit claire, puis l''ajouter à la sauce avec le bouillon. Bien mélanger, saler et porter à ébullition.","image":null},{"text":"Couvrir d''une feuille d''aluminium puis du couvercle et cuire 30 minutes à feu très doux, sans remuer, pour que le riz cuise à la vapeur.","image":null},{"text":"En fin de cuisson, monter le feu 3 à 4 minutes pour laisser le fond accrocher légèrement, puis égrainer à la fourchette avant de servir.","image":null}]'::jsonb, array['Servez avec du plantain frit (dodo) et du poulet grillé, comme dans les fêtes de Lagos.', 'Ne remuez pas le riz pendant la cuisson : c''est la vapeur qui le cuit.']::text[], array['fête', 'tomate', 'riz']::text[], true, true, '2026-02-15T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000010', 'soupe-egusi', 'Soupe egusi', 'NG', 'Pays yoruba et igbo', 'mijotes', 'Sauce épaisse aux graines de melon moulues, légumes-feuilles et poisson fumé.', 'L''egusi désigne les graines d''une variété de melon cultivée pour ses pépins, que l''on sèche puis que l''on moud. Au Nigeria, la soupe egusi se prépare aussi bien chez les Yorubas que chez les Igbos, chacun avec sa manière de cuire les graines : en petits grumeaux ou en sauce lisse.

On la déguste avec une boule d''igname pilée, d''eba ou de fufu, que l''on façonne du bout des doigts pour attraper la sauce.', '/recipes/soupe-egusi.webp', 25, 50, 6, 2, '[{"quantity":250,"unit":"g","name":"graines d''egusi moulues","productSlug":"graines-d-egusi"},{"quantity":600,"unit":"g","name":"bœuf en morceaux","productSlug":null},{"quantity":150,"unit":"g","name":"poisson fumé émietté","productSlug":"poisson-fume"},{"quantity":40,"unit":"g","name":"crevettes séchées moulues","productSlug":"crevettes-sechees"},{"quantity":12,"unit":"cl","name":"huile de palme rouge","productSlug":"huile-de-palme-rouge"},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":2,"unit":null,"name":"piments rouges","productSlug":null},{"quantity":300,"unit":"g","name":"épinards frais (ou feuilles amères)","productSlug":null},{"quantity":1,"unit":null,"name":"cube de bouillon","productSlug":null},{"quantity":null,"unit":null,"name":"sel","productSlug":null}]'::jsonb, '[{"text":"Cuire le bœuf avec un oignon émincé, le cube de bouillon et 50 cl d''eau pendant 30 minutes. Réserver la viande et le bouillon.","image":null},{"text":"Mélanger les graines d''egusi moulues avec le second oignon mixé et un peu d''eau pour obtenir une pâte épaisse.","image":null},{"text":"Faire chauffer l''huile de palme dans une cocotte 2 minutes sans la laisser fumer, puis déposer la pâte d''egusi par cuillerées. Laisser frire 10 minutes en retournant délicatement pour former des grumeaux dorés.","image":null},{"text":"Verser le bouillon de cuisson, ajouter la viande, le poisson fumé, les crevettes séchées et les piments mixés. Couvrir et laisser mijoter 15 minutes à feu doux.","image":null},{"text":"Ajouter les épinards hachés, mélanger et cuire encore 5 minutes. Rectifier l''assaisonnement.","image":null}]'::jsonb, array['Pour une sauce plus lisse, délayez l''egusi dans le bouillon au lieu de le frire.', 'Servez avec du fufu ou de l''igname pilée.']::text[], array['egusi', 'huile de palme', 'poisson fumé']::text[], false, true, '2026-02-16T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000011', 'sauce-graine', 'Sauce graine au poulet', 'CI', 'Sud de la Côte d''Ivoire', 'mijotes', 'Poulet mijoté dans une sauce onctueuse à la pulpe de noix de palme.', 'La « graine », c''est la noix de palme, que l''on fait bouillir puis que l''on pile pour en extraire une pulpe orangée et parfumée. La sauce graine est l''un des grands classiques de la cuisine ivoirienne, surtout dans le Sud forestier où poussent les palmiers à huile.

On la sert le dimanche avec du riz blanc, du foutou banane ou du placali, et chaque famille garde jalousement sa manière de la parfumer.', '/recipes/sauce-graine.webp', 20, 70, 6, 2, '[{"quantity":800,"unit":"g","name":"pulpe de noix de palme","productSlug":"pulpe-de-noix-de-palme"},{"quantity":1.2,"unit":"kg","name":"poulet fermier découpé","productSlug":null},{"quantity":150,"unit":"g","name":"poisson fumé","productSlug":"poisson-fume"},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":3,"unit":null,"name":"tomates","productSlug":null},{"quantity":3,"unit":"gousses","name":"ail","productSlug":null},{"quantity":2,"unit":null,"name":"piments frais","productSlug":null},{"quantity":6,"unit":null,"name":"gombos frais","productSlug":null},{"quantity":1,"unit":"l","name":"eau","productSlug":null},{"quantity":null,"unit":null,"name":"sel et poivre","productSlug":null}]'::jsonb, '[{"text":"Assaisonner le poulet avec l''ail écrasé, un oignon émincé, du sel et du poivre. Le faire revenir 10 minutes dans une cocotte avec un fond d''eau, à couvert.","image":null},{"text":"Délayer la pulpe de noix de palme dans 1 litre d''eau chaude, puis la verser sur le poulet.","image":null},{"text":"Ajouter les tomates et le second oignon entiers, les piments et les gombos. Laisser cuire 20 minutes, puis retirer tomates, oignon et gombos, les écraser et les remettre dans la sauce.","image":null},{"text":"Ajouter le poisson fumé émietté et laisser mijoter 35 minutes à feu doux, en remuant de temps en temps, jusqu''à ce que l''huile rouge remonte en surface.","image":null},{"text":"Goûter, rectifier le sel et servir bien chaud.","image":null}]'::jsonb, array['La sauce est prête quand une fine couche d''huile rouge brille à la surface.', 'Accompagnez de riz blanc ou de foutou banane.']::text[], array['noix de palme', 'poulet', 'dimanche']::text[], false, true, '2026-02-17T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000012', 'garba', 'Garba', 'CI', 'Abidjan', 'accompagnements', 'Attiéké et thon frit croustillant, piment et oignon : le plat de rue d''Abidjan.', 'Le garba est né dans les petits kiosques d''Abidjan, les « garbadromes », tenus à l''origine par des vendeurs venus du Niger, selon la tradition populaire. Pour quelques pièces, on y sert une montagne d''attiéké, un morceau de thon frit et une poignée de piment.

Étudiants, travailleurs et noctambules en ont fait un véritable symbole de la ville, célébré jusque dans les chansons de coupé-décalé.', '/recipes/garba.webp', 20, 20, 4, 1, '[{"quantity":500,"unit":"g","name":"attiéké sec","productSlug":"attieke-sec"},{"quantity":800,"unit":"g","name":"thon frais en tranches épaisses","productSlug":null},{"quantity":2,"unit":null,"name":"oignons rouges","productSlug":null},{"quantity":2,"unit":null,"name":"tomates","productSlug":null},{"quantity":3,"unit":null,"name":"piments verts frais","productSlug":null},{"quantity":1,"unit":null,"name":"cube de bouillon","productSlug":null},{"quantity":50,"unit":"cl","name":"huile de friture","productSlug":null},{"quantity":null,"unit":null,"name":"sel et poivre","productSlug":null}]'::jsonb, '[{"text":"Arroser l''attiéké sec de 30 cl d''eau tiède salée, bien l''égrainer avec les doigts et laisser gonfler 10 minutes à couvert.","image":null},{"text":"Cuire l''attiéké 10 minutes à la vapeur dans un couscoussier, puis l''égrainer de nouveau à la fourchette.","image":null},{"text":"Couper le thon en gros morceaux, l''assaisonner avec le cube de bouillon émietté, du sel et du poivre.","image":null},{"text":"Faire chauffer l''huile et frire le thon 6 à 8 minutes, jusqu''à ce qu''il soit bien doré et croustillant à l''extérieur. Égoutter sur du papier absorbant.","image":null},{"text":"Émincer finement les oignons, couper les tomates en dés et hacher les piments. Servir l''attiéké en dôme, le thon par-dessus, garni d''oignon, de tomate et de piment, avec un filet d''huile de friture.","image":null}]'::jsonb, array['À Abidjan, on arrose souvent le garba d''un peu d''huile de friture du thon : c''est ce qui fait son goût.', 'Mangez-le à la main, comme dans les garbadromes.']::text[], array['plat de rue', 'attiéké', 'poisson']::text[], true, true, '2026-02-18T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000013', 'kedjenou', 'Kedjenou de poulet', 'CI', 'Pays baoulé', 'mijotes', 'Poulet cuit à l''étouffée dans son jus, avec légumes et piment, sans ajout d''eau.', 'Le kedjenou vient du pays baoulé, au centre de la Côte d''Ivoire. Son nom évoquerait le geste de secouer le canari, la marmite en terre cuite fermée par des feuilles de bananier, que l''on remue régulièrement au lieu d''ouvrir.

La viande cuit ainsi à l''étouffée, dans sa propre eau et celle des légumes, ce qui lui donne une chair tendre et une sauce courte, très parfumée.', '/recipes/kedjenou.webp', 20, 60, 4, 1, '[{"quantity":1.5,"unit":"kg","name":"poulet fermier découpé","productSlug":null},{"quantity":3,"unit":null,"name":"tomates","productSlug":null},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":1,"unit":null,"name":"aubergine","productSlug":null},{"quantity":1,"unit":"morceau","name":"gingembre frais (4 cm)","productSlug":null},{"quantity":3,"unit":"gousses","name":"ail","productSlug":null},{"quantity":2,"unit":null,"name":"piments frais","productSlug":null},{"quantity":2,"unit":null,"name":"feuilles de laurier","productSlug":null},{"quantity":1,"unit":null,"name":"cube de bouillon","productSlug":null},{"quantity":null,"unit":null,"name":"poivre de Penja","productSlug":"poivre-de-penja"},{"quantity":null,"unit":null,"name":"sel","productSlug":null}]'::jsonb, '[{"text":"Couper les tomates, les oignons et l''aubergine en morceaux. Écraser l''ail et le gingembre en pâte.","image":null},{"text":"Mettre dans une cocotte en fonte (ou un canari) le poulet, les légumes, l''ail, le gingembre, les piments entiers, le laurier et le cube émietté. Saler et poivrer. Ne pas ajouter d''eau.","image":null},{"text":"Fermer hermétiquement : placer une feuille d''aluminium sous le couvercle pour qu''aucune vapeur ne s''échappe.","image":null},{"text":"Cuire 55 à 60 minutes à feu doux. Toutes les 10 minutes, secouer vigoureusement la cocotte en la tenant par les anses, sans l''ouvrir.","image":null},{"text":"Vérifier la cuisson : le poulet doit être tendre et nappé d''une sauce courte. Retirer les piments si l''on souhaite moins de piquant.","image":null}]'::jsonb, array['Résistez à l''envie d''ouvrir la cocotte : toute la vapeur doit rester à l''intérieur.', 'Servez avec de l''attiéké ou du riz blanc.']::text[], array['poulet', 'étouffée', 'canari']::text[], false, true, '2026-02-19T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000014', 'to-sauce-gombo', 'Tô et sauce gombo', 'BF', 'Plateau central', 'accompagnements', 'Pâte de maïs ferme servie avec une sauce gombo filante au soumbala.', 'Le tô est la base des repas au Burkina Faso : une pâte ferme de farine de mil, de sorgho ou de maïs, que l''on découpe à la main et que l''on trempe dans la sauce. Chaque soir, dans les cours familiales, les grandes marmites de tô se préparent au feu de bois.

La sauce gombo, légèrement filante, en est la compagne la plus courante. Le soumbala, condiment fermenté à base de graines de néré, lui apporte son parfum profond si caractéristique.', '/recipes/to-sauce-gombo.webp', 20, 45, 6, 2, '[{"quantity":600,"unit":"g","name":"farine de maïs blanc","productSlug":null},{"quantity":2,"unit":"l","name":"eau","productSlug":null},{"quantity":1,"unit":"c. à soupe","name":"jus de citron (ou d''eau de tamarin)","productSlug":null},{"quantity":60,"unit":"g","name":"gombo séché en poudre","productSlug":"gombo-seche"},{"quantity":2,"unit":"c. à soupe","name":"soumbala","productSlug":"soumbala"},{"quantity":400,"unit":"g","name":"viande de mouton ou de bœuf en morceaux","productSlug":null},{"quantity":100,"unit":"g","name":"poisson fumé","productSlug":"poisson-fume"},{"quantity":1,"unit":null,"name":"oignon","productSlug":null},{"quantity":2,"unit":null,"name":"piments frais","productSlug":null},{"quantity":5,"unit":"cl","name":"huile d''arachide","productSlug":null},{"quantity":null,"unit":null,"name":"sel","productSlug":null}]'::jsonb, '[{"text":"Sauce : faire revenir la viande dans l''huile avec l''oignon émincé, couvrir de 1 litre d''eau et cuire 30 minutes.","image":null},{"text":"Ajouter le soumbala écrasé, le poisson fumé émietté et les piments. Laisser frémir 5 minutes, puis verser la poudre de gombo en pluie en fouettant pour éviter les grumeaux. Cuire 8 minutes : la sauce doit devenir filante.","image":null},{"text":"Tô : délayer 150 g de farine dans 50 cl d''eau froide. Porter 1,5 litre d''eau à ébullition avec le jus de citron, puis y verser ce mélange en remuant pour obtenir une bouillie.","image":null},{"text":"Retirer un bol de bouillie et le réserver. Incorporer le reste de la farine au bâton ou à la spatule, par petites quantités, en écrasant la pâte contre la paroi pour qu''elle soit bien lisse.","image":null},{"text":"Quand la pâte devient ferme et se détache des bords, rajouter un peu de bouillie réservée si elle est trop épaisse, couvrir et laisser cuire 5 minutes à feu très doux.","image":null},{"text":"Façonner le tô en dômes à l''aide d''une louche mouillée et servir avec la sauce gombo à côté.","image":null}]'::jsonb, array['Le jus de citron ou de tamarin donne au tô sa légère acidité et l''empêche de coller.', 'On mange le tô à la main droite, en formant une petite boulette que l''on plonge dans la sauce.']::text[], array['gombo', 'soumbala', 'quotidien']::text[], false, true, '2026-02-20T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000015', 'thiere-mbuum', 'Thiéré mbuum', 'SN', 'Saloum et pays sérère', 'riz-cereales', 'Couscous de mil aux feuilles de moringa, servi avec une sauce de viande et niébé.', 'Le thiéré est le couscous de mil du Sénégal, roulé à la main et cuit à la vapeur. Associé au mbuum, les feuilles de moringa (nébédaye en wolof), il devient un plat de fête très apprécié, notamment chez les Sérères et dans le Saloum.

On le prépare en grande quantité pour la Tamkharit, le Nouvel An musulman, ou pour recevoir. Les feuilles donnent au couscous une couleur verte et une saveur végétale légèrement poivrée.', '/recipes/thiere-mbuum.webp', 30, 75, 6, 2, '[{"quantity":750,"unit":"g","name":"couscous de mil (thiéré)","productSlug":"couscous-de-mil"},{"quantity":40,"unit":"g","name":"feuilles de moringa séchées","productSlug":"feuilles-de-moringa"},{"quantity":150,"unit":"g","name":"niébé (haricots cornille)","productSlug":null},{"quantity":800,"unit":"g","name":"viande de mouton en morceaux","productSlug":null},{"quantity":150,"unit":"g","name":"pâte d''arachide","productSlug":"pate-d-arachide"},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":2,"unit":"c. à soupe","name":"concentré de tomate","productSlug":null},{"quantity":1,"unit":"c. à café","name":"poivre de Sélim moulu","productSlug":"poivre-de-selim"},{"quantity":5,"unit":"cl","name":"huile d''arachide","productSlug":null},{"quantity":30,"unit":"g","name":"beurre","productSlug":null},{"quantity":null,"unit":null,"name":"sel","productSlug":null}]'::jsonb, '[{"text":"Faire tremper le niébé 2 heures (ou la veille), puis le cuire 40 minutes à l''eau salée.","image":null},{"text":"Sauce : faire revenir le mouton dans l''huile avec les oignons émincés, ajouter le concentré de tomate et couvrir de 1,2 litre d''eau. Cuire 45 minutes, puis délayer la pâte d''arachide dans la sauce et laisser mijoter encore 15 minutes. Ajouter le niébé en fin de cuisson.","image":null},{"text":"Humecter le couscous de mil avec 15 cl d''eau salée, l''égrainer et le cuire 20 minutes à la vapeur au-dessus d''une marmite d''eau frémissante.","image":null},{"text":"Réhydrater les feuilles de moringa 5 minutes dans un peu d''eau tiède, les égoutter, puis les mélanger au couscous avec le beurre et le poivre de Sélim.","image":null},{"text":"Remettre le couscous 15 minutes à la vapeur pour qu''il s''imprègne du parfum des feuilles, puis l''égrainer à la main.","image":null},{"text":"Servir le thiéré en large plat, arrosé de sauce, avec la viande et le niébé par-dessus.","image":null}]'::jsonb, array['Le couscous doit rester bien égrainé : travaillez-le avec les mains légèrement huilées entre deux cuissons.', 'À la Tamkharit, on le sert souvent avec une sauce tomate au poulet.']::text[], array['mil', 'moringa', 'fête']::text[], false, true, '2026-02-21T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000016', 'caldou', 'Caldou de poisson', 'SN', 'Casamance, Ziguinchor', 'mijotes', 'Poisson poché dans un bouillon citronné, relevé de piment et de gombo.', 'Le caldou est un plat emblématique de la Casamance, au sud du Sénégal. Son nom viendrait du portugais « caldo », bouillon, un héritage des échanges anciens avec les comptoirs portugais de la région.

Frais et acidulé, il met en valeur le poisson du fleuve et de la côte : un bouillon léger au citron, relevé de piment, que l''on verse sur un riz blanc bien cuit.', '/recipes/caldou.webp', 20, 35, 4, 1, '[{"quantity":1.2,"unit":"kg","name":"poisson blanc à chair ferme (thiof, capitaine ou dorade) en tranches","productSlug":null},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":2,"unit":null,"name":"tomates","productSlug":null},{"quantity":3,"unit":null,"name":"citrons verts","productSlug":null},{"quantity":8,"unit":null,"name":"gombos frais","productSlug":null},{"quantity":1,"unit":null,"name":"piment frais","productSlug":null},{"quantity":3,"unit":"gousses","name":"ail","productSlug":null},{"quantity":1,"unit":"c. à soupe","name":"guedj émietté","productSlug":"guedj"},{"quantity":5,"unit":"cl","name":"huile d''arachide","productSlug":null},{"quantity":null,"unit":null,"name":"poivre de Penja","productSlug":"poivre-de-penja"},{"quantity":null,"unit":null,"name":"sel","productSlug":null}]'::jsonb, '[{"text":"Nettoyer le poisson et le frotter avec le jus d''un citron, l''ail écrasé, du sel et du poivre. Laisser mariner 15 minutes.","image":null},{"text":"Dans une cocotte, faire revenir doucement les oignons émincés dans l''huile, sans les colorer. Ajouter les tomates coupées en dés et cuire 5 minutes.","image":null},{"text":"Verser 1 litre d''eau, ajouter le guedj, le piment entier et les gombos. Porter à frémissement et cuire 10 minutes.","image":null},{"text":"Déposer délicatement les tranches de poisson dans le bouillon et les pocher 12 à 15 minutes à feu doux, sans remuer pour ne pas les briser.","image":null},{"text":"Hors du feu, ajouter le jus des deux citrons restants, goûter et rectifier l''assaisonnement.","image":null}]'::jsonb, array['Servez sur du riz blanc, en arrosant généreusement de bouillon.', 'Ajoutez le citron au dernier moment pour garder toute sa fraîcheur.']::text[], array['poisson', 'citron', 'Casamance']::text[], false, true, '2026-02-22T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000017', 'fufu-light-soup', 'Fufu et light soup', 'GH', 'Pays ashanti, Kumasi', 'accompagnements', 'Boule de fufu moelleuse plongée dans une soupe légère à la tomate et au piment.', 'Au Ghana, le fufu est traditionnellement obtenu en pilant manioc et plantain cuits dans un grand mortier, un travail à deux qui rythme la vie des cours ashanti. La « light soup », comme son nom l''indique, est un bouillon clair de tomate et de piment, sans pâte d''arachide ni noix de palme.

L''association des deux est un grand classique du déjeuner du dimanche. On ne mâche pas le fufu : on en détache un morceau du bout des doigts et on l''avale avec la soupe.', '/recipes/fufu-light-soup.webp', 25, 50, 4, 2, '[{"quantity":500,"unit":"g","name":"farine de foufou","productSlug":"farine-de-foufou"},{"quantity":1,"unit":"kg","name":"poulet ou chèvre en morceaux","productSlug":null},{"quantity":4,"unit":null,"name":"tomates","productSlug":null},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":1,"unit":"morceau","name":"gingembre frais (3 cm)","productSlug":null},{"quantity":2,"unit":null,"name":"piments scotch bonnet","productSlug":null},{"quantity":2,"unit":null,"name":"aubergines africaines (garden eggs)","productSlug":null},{"quantity":100,"unit":"g","name":"poisson fumé","productSlug":"poisson-fume"},{"quantity":null,"unit":null,"name":"sel","productSlug":null}]'::jsonb, '[{"text":"Assaisonner la viande avec un oignon mixé, le gingembre râpé et du sel. La faire suer 10 minutes à couvert dans une marmite, sans eau.","image":null},{"text":"Ajouter 1,5 litre d''eau, les tomates, le second oignon, les piments et les aubergines entiers. Cuire 15 minutes, puis retirer les légumes.","image":null},{"text":"Mixer les légumes cuits avec un peu de bouillon, puis les passer au tamis au-dessus de la marmite. Ajouter le poisson fumé et laisser mijoter 20 minutes.","image":null},{"text":"Pendant ce temps, porter 75 cl d''eau à ébullition. Hors du feu, verser la farine de foufou en pluie en remuant vigoureusement avec une spatule solide.","image":null},{"text":"Remettre sur feu doux et travailler la pâte 5 à 8 minutes en la rabattant sans cesse, jusqu''à ce qu''elle soit lisse, élastique et brillante. Former des boules avec les mains mouillées.","image":null},{"text":"Déposer une boule de fufu dans chaque bol creux et la recouvrir de light soup bien chaude, avec les morceaux de viande.","image":null}]'::jsonb, array['Mouillez vos mains à l''eau froide pour façonner le fufu sans qu''il colle.', 'Pour une soupe plus relevée, écrasez un piment dans le bol au moment de servir.']::text[], array['fufu', 'soupe', 'dimanche']::text[], false, true, '2026-02-23T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000018', 'waakye', 'Waakye', 'GH', 'Nord du Ghana et Accra', 'riz-cereales', 'Riz et haricots cuits ensemble, teintés de rouge brun par les feuilles de sorgho.', 'Le waakye (prononcer « waa-tchi ») viendrait des peuples haoussas du nord du Ghana, avant de conquérir Accra et tout le pays. Son nom signifierait simplement « riz et haricots » en haoussa.

Sa couleur brun-rouge caractéristique vient des feuilles de sorgho séchées que l''on fait cuire avec le riz. Le matin, les vendeuses le servent sur une feuille de bananier avec du shito, du gari, des spaghettis, un œuf dur et du poisson frit.', '/recipes/waakye.webp', 15, 70, 6, 1, '[{"quantity":400,"unit":"g","name":"riz long grain","productSlug":null},{"quantity":250,"unit":"g","name":"haricots rouges ou niébé secs","productSlug":null},{"quantity":6,"unit":null,"name":"feuilles de sorgho séchées","productSlug":"feuilles-de-sorgho"},{"quantity":0.5,"unit":"c. à café","name":"bicarbonate de soude (facultatif)","productSlug":null},{"quantity":1.5,"unit":"l","name":"eau","productSlug":null},{"quantity":null,"unit":null,"name":"sel","productSlug":null},{"quantity":6,"unit":null,"name":"œufs durs (pour servir)","productSlug":null},{"quantity":150,"unit":"g","name":"gari (semoule de manioc, pour servir)","productSlug":null}]'::jsonb, '[{"text":"Faire tremper les haricots 8 heures dans l''eau froide, puis les égoutter.","image":null},{"text":"Rincer les feuilles de sorgho et les déchirer en gros morceaux. Les mettre dans une marmite avec les haricots, le bicarbonate et 1,5 litre d''eau.","image":null},{"text":"Cuire 40 minutes à feu moyen, jusqu''à ce que les haricots soient presque tendres et que l''eau ait pris une couleur rouge sombre.","image":null},{"text":"Rincer le riz jusqu''à ce que l''eau soit claire, l''ajouter à la marmite avec du sel. L''eau doit dépasser le riz d''environ 1 cm ; en rajouter si besoin.","image":null},{"text":"Couvrir et cuire 25 minutes à feu doux, jusqu''à absorption complète du liquide. Retirer les feuilles de sorgho et égrainer à la fourchette.","image":null},{"text":"Servir avec des œufs durs, du gari et, selon les goûts, du shito, du poisson frit et une salade de chou.","image":null}]'::jsonb, array['Le bicarbonate accentue la couleur rouge, mais n''en mettez pas trop : une demi-cuillère suffit.', 'Le waakye se déguste traditionnellement au petit-déjeuner, sur une feuille de bananier.']::text[], array['riz', 'haricots', 'plat de rue']::text[], true, true, '2026-02-24T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000019', 'poulet-dg', 'Poulet DG', 'CM', 'Douala et Yaoundé', 'mijotes', 'Poulet doré et plantains mûrs sautés avec carottes, haricots verts et poivrons.', 'Le poulet DG, pour « directeur général », serait né dans les années 1980 dans les restaurants de Douala. On raconte qu''il était alors réservé aux tables des patrons, tant le poulet et le plantain frit y étaient servis avec générosité.

Devenu un classique des fêtes et des repas du dimanche dans tout le Cameroun, il réunit dans une même sauteuse le poulet doré, les plantains bien mûrs et une poêlée de légumes colorés.', '/recipes/poulet-dg.webp', 30, 60, 6, 2, '[{"quantity":1.5,"unit":"kg","name":"poulet fermier découpé en morceaux","productSlug":null},{"quantity":4,"unit":null,"name":"plantains bien mûrs (peau noircie)","productSlug":null},{"quantity":3,"unit":null,"name":"carottes","productSlug":null},{"quantity":200,"unit":"g","name":"haricots verts","productSlug":null},{"quantity":1,"unit":null,"name":"poivron vert","productSlug":null},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":3,"unit":null,"name":"tomates","productSlug":null},{"quantity":4,"unit":"gousses","name":"ail","productSlug":null},{"quantity":1,"unit":"morceau","name":"gingembre frais (4 cm)","productSlug":null},{"quantity":15,"unit":"cl","name":"huile de friture","productSlug":null},{"quantity":null,"unit":null,"name":"poivre blanc de Penja","productSlug":"poivre-de-penja"},{"quantity":null,"unit":null,"name":"sel","productSlug":null}]'::jsonb, '[{"text":"Mixer l''ail, le gingembre et un oignon avec un peu d''eau. Frotter les morceaux de poulet avec ce mélange, saler, poivrer au poivre de Penja et laisser mariner au moins 30 minutes.","image":null},{"text":"Placer le poulet dans une cocotte avec un verre d''eau, couvrir et cuire 20 minutes à feu moyen. Égoutter les morceaux en réservant le bouillon.","image":null},{"text":"Faire dorer le poulet dans une poêle avec un peu d''huile chaude jusqu''à ce que la peau soit bien colorée, puis réserver.","image":null},{"text":"Éplucher les plantains, les couper en rondelles épaisses en biais et les frire dans l''huile chaude 3 à 4 minutes de chaque côté. Égoutter sur du papier absorbant.","image":null},{"text":"Dans une grande sauteuse, faire revenir le second oignon émincé, ajouter les tomates concassées, puis les carottes en bâtonnets et les haricots verts. Mouiller avec le bouillon réservé et cuire 10 minutes.","image":null},{"text":"Ajouter le poivron en lanières et le poulet, laisser mijoter 10 minutes, puis incorporer délicatement les plantains. Rectifier l''assaisonnement et servir aussitôt.","image":null}]'::jsonb, array['Choisissez des plantains presque noirs : ils caramélisent à la friture et apportent la note sucrée qui fait tout le charme du plat.', 'Ajoutez les plantains en dernier et remuez à peine pour qu''ils gardent leur forme.']::text[], array['fête', 'plantain', 'poulet']::text[], true, true, '2026-02-25T00:00:00.000Z'),
  ('40000000-0000-4000-a000-00000000001a', 'eru', 'Eru', 'CM', 'Sud-Ouest, Mamfé', 'mijotes', 'Feuilles d''okok finement émincées, mijotées avec waterleaf, huile de palme, viande et poisson fumé.', 'L''eru est la grande spécialité des Bayangi, peuple de la région de Mamfé, dans le Sud-Ouest du Cameroun. Son nom désigne à la fois le plat et la liane sauvage dont on récolte les feuilles, appelée okok dans d''autres régions du pays.

On le sert traditionnellement avec du water fufu, une boule de manioc fermenté, lors des réunions de famille et des cérémonies. Sa texture fondante et son goût fumé en font l''un des plats les plus appréciés du Cameroun anglophone.', '/recipes/eru.webp', 30, 60, 6, 2, '[{"quantity":200,"unit":"g","name":"feuilles d''okok (eru) séchées et émincées","productSlug":"feuilles-d-okok"},{"quantity":1,"unit":"kg","name":"waterleaf frais ou épinards","productSlug":null},{"quantity":500,"unit":"g","name":"bœuf ou peau de bœuf (kanda) en morceaux","productSlug":null},{"quantity":200,"unit":"g","name":"poisson fumé émietté","productSlug":"poisson-fume"},{"quantity":50,"unit":"g","name":"crevettes séchées","productSlug":"crevettes-sechees"},{"quantity":30,"unit":"cl","name":"huile de palme rouge","productSlug":"huile-de-palme-rouge"},{"quantity":1,"unit":null,"name":"oignon","productSlug":null},{"quantity":1,"unit":null,"name":"piment frais","productSlug":null},{"quantity":1,"unit":null,"name":"cube de bouillon","productSlug":null},{"quantity":null,"unit":null,"name":"sel","productSlug":null}]'::jsonb, '[{"text":"Réhydrater les feuilles d''okok 20 minutes dans l''eau tiède, puis les rincer et bien les égoutter.","image":null},{"text":"Cuire la viande 40 minutes dans une marmite avec l''oignon émincé, le cube de bouillon, le sel et juste assez d''eau pour la couvrir.","image":null},{"text":"Laver le waterleaf, l''émincer finement et l''ajouter à la viande. Laisser cuire 5 minutes : les feuilles rendent beaucoup d''eau.","image":null},{"text":"Incorporer le poisson fumé débarrassé de ses arêtes, les crevettes séchées pilées et le piment écrasé. Mélanger.","image":null},{"text":"Ajouter les feuilles d''okok petit à petit en remuant, puis verser l''huile de palme. Couvrir et laisser mijoter 15 minutes à feu doux, jusqu''à ce que le liquide soit presque entièrement absorbé.","image":null},{"text":"Goûter, rectifier le sel et servir bien chaud avec du water fufu ou du garri.","image":null}]'::jsonb, array['Si vous utilisez des épinards, égouttez-les bien après la cuisson : ils contiennent moins d''eau que le waterleaf et l''eru ne doit pas être trop sec pour autant.', 'L''eru est encore meilleur réchauffé le lendemain.']::text[], array['feuilles', 'huile de palme', 'fumé']::text[], false, true, '2026-02-26T00:00:00.000Z'),
  ('40000000-0000-4000-a000-00000000001b', 'koki', 'Koki', 'CM', 'Littoral et Ouest', 'accompagnements', 'Gâteau de haricots cornille à l''huile de palme, cuit à la vapeur en feuilles de bananier.', 'Le koki est un mets très ancien du Cameroun, préparé aussi bien sur la côte que dans l''Ouest du pays. Les haricots cornille, débarrassés de leur peau puis écrasés, sont battus avec l''huile de palme jusqu''à former une pâte orangée et soyeuse.

Enveloppé dans des feuilles de bananier et cuit longuement à la vapeur, il accompagne volontiers le plantain ou le macabo bouillis. On le partage lors des marchés et des fêtes de village.', '/recipes/koki.webp', 60, 120, 8, 3, '[{"quantity":500,"unit":"g","name":"haricots cornille (niébé) secs","productSlug":null},{"quantity":25,"unit":"cl","name":"huile de palme rouge","productSlug":"huile-de-palme-rouge"},{"quantity":1,"unit":null,"name":"oignon","productSlug":null},{"quantity":1,"unit":null,"name":"piment frais","productSlug":null},{"quantity":300,"unit":"g","name":"jeunes feuilles de taro ou épinards","productSlug":null},{"quantity":30,"unit":"cl","name":"eau tiède","productSlug":null},{"quantity":1,"unit":null,"name":"cube de bouillon","productSlug":null},{"quantity":null,"unit":null,"name":"sel","productSlug":null},{"quantity":null,"unit":null,"name":"feuilles de bananier","productSlug":null}]'::jsonb, '[{"text":"Faire tremper les haricots 6 heures dans l''eau froide. Les frotter entre les mains pour retirer les peaux, qui remontent à la surface, puis rincer.","image":null},{"text":"Mixer les haricots avec l''oignon, le piment et un peu d''eau tiède jusqu''à obtenir une pâte très fine et lisse.","image":null},{"text":"Faire tiédir l''huile de palme sans la laisser fumer, puis l''incorporer peu à peu à la pâte en battant vigoureusement. Ajouter le reste d''eau, le cube émietté, le sel et les feuilles de taro émincées.","image":null},{"text":"Passer les feuilles de bananier quelques secondes au-dessus d''une flamme pour les assouplir. Déposer une louche de pâte au centre de chaque feuille et refermer en paquet bien serré.","image":null},{"text":"Tapisser le fond d''une grande marmite de tiges ou de feuilles de bananier, ajouter un fond d''eau et y ranger les paquets. Couvrir et cuire 2 heures à feu moyen, en rajoutant de l''eau si nécessaire.","image":null},{"text":"Le koki est cuit lorsqu''il est ferme au toucher. Laisser reposer 10 minutes avant d''ouvrir les paquets.","image":null}]'::jsonb, array['Plus la pâte est battue, plus le koki est léger : n''hésitez pas à fouetter plusieurs minutes.', 'À défaut de feuilles de bananier, utilisez des ramequins filmés ou du papier aluminium.']::text[], array['haricots', 'vapeur', 'huile de palme']::text[], false, true, '2026-02-27T00:00:00.000Z'),
  ('40000000-0000-4000-a000-00000000001c', 'moambe', 'Poulet à la moambé', 'CD', 'Kinshasa', 'mijotes', 'Poulet mijoté dans une sauce onctueuse à la noix de palme et à la pâte d''arachide.', 'La moambé est souvent présentée comme le plat national de la République démocratique du Congo, et on la retrouve aussi au Congo-Brazzaville, en Angola et en Centrafrique. Son nom viendrait du lingala et désigne la sauce obtenue à partir de la pulpe des noix de palme.

Chaque famille a sa version : certaines y ajoutent de la pâte d''arachide pour une sauce plus ronde, d''autres la préfèrent nature. On la sert avec du riz, du fufu ou de la chikwangue.', '/recipes/moambe.webp', 25, 75, 6, 2, '[{"quantity":1.5,"unit":"kg","name":"poulet découpé en morceaux","productSlug":null},{"quantity":400,"unit":"g","name":"pulpe de noix de palme","productSlug":"pulpe-de-noix-de-palme"},{"quantity":3,"unit":"c. à soupe","name":"pâte d''arachide","productSlug":"pate-d-arachide"},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":3,"unit":null,"name":"tomates","productSlug":null},{"quantity":3,"unit":"gousses","name":"ail","productSlug":null},{"quantity":1,"unit":null,"name":"piment frais","productSlug":null},{"quantity":2,"unit":"c. à soupe","name":"huile","productSlug":null},{"quantity":1,"unit":null,"name":"cube de bouillon","productSlug":null},{"quantity":null,"unit":null,"name":"sel","productSlug":null}]'::jsonb, '[{"text":"Saler les morceaux de poulet et les faire dorer dans l''huile chaude dans une cocotte, 10 minutes environ. Réserver.","image":null},{"text":"Dans la même cocotte, faire revenir les oignons émincés et l''ail haché, puis ajouter les tomates concassées et cuire 5 minutes.","image":null},{"text":"Délayer la pulpe de noix de palme dans 50 cl d''eau chaude, verser dans la cocotte et porter à frémissement.","image":null},{"text":"Remettre le poulet, ajouter le cube de bouillon et le piment entier. Couvrir et laisser mijoter 40 minutes à feu doux.","image":null},{"text":"Délayer la pâte d''arachide dans une louche de sauce, puis l''incorporer. Cuire encore 15 minutes à découvert en remuant, jusqu''à ce que la sauce nappe la cuillère et que l''huile remonte à la surface.","image":null},{"text":"Retirer le piment, rectifier l''assaisonnement et servir avec du riz blanc ou du fufu.","image":null}]'::jsonb, array['Laissez le piment entier pour parfumer sans trop relever ; percez-le si vous aimez une sauce plus piquante.', 'Un poulet fermier, plus ferme, supporte mieux la longue cuisson.']::text[], array['noix de palme', 'arachide', 'poulet']::text[], false, true, '2026-02-28T00:00:00.000Z'),
  ('40000000-0000-4000-a000-00000000001d', 'liboke-de-poisson', 'Liboké de poisson', 'CG', 'Brazzaville et bords du fleuve Congo', 'grillades', 'Poisson aux tomates et aux aromates en papillote de feuilles de bananier, cuit sur la braise.', 'Le liboké (pluriel : maboké) est une technique de cuisson emblématique des deux rives du fleuve Congo. Le mot, issu du lingala, désigne le paquet de feuilles de bananier dans lequel on enferme poisson, viande ou légumes avant de le poser sur les braises.

Les pêcheurs du fleuve préparent ainsi le capitaine, le silure ou la carpe, qui cuisent doucement dans leur propre jus. À Brazzaville, le liboké de poisson reste un incontournable des repas partagés en plein air.', '/recipes/liboke-de-poisson.webp', 25, 35, 4, 2, '[{"quantity":1,"unit":"kg","name":"poisson ferme (capitaine, tilapia ou carpe) en tronçons","productSlug":null},{"quantity":3,"unit":null,"name":"tomates","productSlug":null},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":3,"unit":"gousses","name":"ail","productSlug":null},{"quantity":1,"unit":"morceau","name":"gingembre frais (3 cm)","productSlug":null},{"quantity":1,"unit":null,"name":"piment frais","productSlug":null},{"quantity":1,"unit":"botte","name":"ciboule","productSlug":null},{"quantity":4,"unit":null,"name":"grains de poivre de Selim","productSlug":"poivre-de-selim"},{"quantity":2,"unit":"c. à soupe","name":"huile","productSlug":null},{"quantity":null,"unit":null,"name":"sel","productSlug":null},{"quantity":null,"unit":null,"name":"feuilles de bananier","productSlug":null}]'::jsonb, '[{"text":"Écailler et vider le poisson, le rincer, puis le couper en tronçons. Saler légèrement.","image":null},{"text":"Piler ou mixer l''ail, le gingembre, le piment et les grains de poivre de Selim légèrement écrasés. Frotter le poisson avec cette pâte et laisser reposer 15 minutes.","image":null},{"text":"Couper les tomates et les oignons en dés, ciseler la ciboule et mélanger le tout avec l''huile.","image":null},{"text":"Passer les feuilles de bananier au-dessus d''une flamme pour les assouplir. Sur deux feuilles croisées, déposer une couche de légumes, le poisson, puis le reste des légumes.","image":null},{"text":"Refermer en paquet bien serré et ficeler avec une lanière de feuille ou de la ficelle de cuisine. Emballer d''une seconde feuille pour éviter les fuites.","image":null},{"text":"Poser les papillotes sur des braises moyennes et cuire 30 à 35 minutes en les retournant à mi-cuisson. Ouvrir à table pour profiter du parfum.","image":null}]'::jsonb, array['Au four, comptez 35 minutes à 200 °C, papillotes posées sur une plaque.', 'Servez avec de la chikwangue ou des bananes plantains bouillies.']::text[], array['papillote', 'braise', 'poisson']::text[], false, true, '2026-03-01T00:00:00.000Z'),
  ('40000000-0000-4000-a000-00000000001e', 'poulet-odika', 'Poulet à l''odika', 'GA', 'Libreville', 'mijotes', 'Poulet fumé mijoté dans une sauce sombre et onctueuse au « chocolat indigène ».', 'L''odika, que les Gabonais surnomment volontiers « chocolat indigène », est une pâte faite des amandes grillées de la mangue sauvage. Moulue puis moulée en pains sombres, elle est vendue sur tous les marchés du Gabon.

Râpée dans la sauce, elle lui donne une couleur brune, une consistance veloutée et un goût légèrement fumé. Le poulet à l''odika est l''un des plats les plus représentatifs de la cuisine gabonaise, souvent servi avec du manioc ou du riz.', '/recipes/poulet-odika.webp', 20, 60, 6, 2, '[{"quantity":1.5,"unit":"kg","name":"poulet (idéalement fumé) en morceaux","productSlug":null},{"quantity":100,"unit":"g","name":"odika râpé","productSlug":"odika"},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":2,"unit":null,"name":"tomates","productSlug":null},{"quantity":3,"unit":"gousses","name":"ail","productSlug":null},{"quantity":1,"unit":null,"name":"piment frais","productSlug":null},{"quantity":5,"unit":"cl","name":"huile de palme rouge","productSlug":"huile-de-palme-rouge"},{"quantity":1,"unit":null,"name":"cube de bouillon","productSlug":null},{"quantity":null,"unit":null,"name":"sel","productSlug":null}]'::jsonb, '[{"text":"Faire revenir les morceaux de poulet dans l''huile de palme chaude pendant 10 minutes, jusqu''à ce qu''ils soient dorés.","image":null},{"text":"Ajouter les oignons émincés, l''ail haché et les tomates concassées. Laisser fondre 5 minutes.","image":null},{"text":"Mouiller avec 60 cl d''eau, ajouter le cube de bouillon et le piment entier. Couvrir et laisser mijoter 30 minutes.","image":null},{"text":"Râper finement l''odika et le délayer dans une louche de bouillon chaud jusqu''à obtenir une crème lisse.","image":null},{"text":"Verser l''odika dans la cocotte en remuant sans cesse, puis cuire 15 minutes à feu doux : la sauce épaissit et devient brune et brillante.","image":null},{"text":"Rectifier le sel, retirer le piment et servir avec du bâton de manioc ou du riz.","image":null}]'::jsonb, array['Chauffez légèrement le pain d''odika au-dessus d''une flamme : il se râpe beaucoup plus facilement.', 'Remuez bien après l''ajout d''odika, la sauce accroche vite au fond de la marmite.']::text[], array['odika', 'poulet', 'Gabon']::text[], false, true, '2026-03-02T00:00:00.000Z'),
  ('40000000-0000-4000-a000-00000000001f', 'puff-puff', 'Puff-puff', 'NG', 'Lagos', 'douceurs', 'Petits beignets levés, dorés dehors et moelleux dedans, parfumés à la muscade.', 'Le puff-puff est l''un des en-cas de rue les plus populaires du Nigeria, vendu tout chaud dans des sachets en papier au coin des rues de Lagos. On le retrouve sous d''autres noms dans toute la région : bofrot au Ghana, beignets ou « boules » au Cameroun, mikate au Congo.

Simple pâte levée frite en petites boules, il accompagne les fêtes, les anniversaires et les goûters. On le mange nature, saupoudré de sucre ou accompagné d''une sauce pimentée.', '/recipes/puff-puff.webp', 15, 20, 6, 1, '[{"quantity":500,"unit":"g","name":"farine de blé","productSlug":null},{"quantity":100,"unit":"g","name":"sucre","productSlug":null},{"quantity":7,"unit":"g","name":"levure de boulanger sèche","productSlug":null},{"quantity":1,"unit":"c. à café","name":"noix de muscade râpée","productSlug":null},{"quantity":1,"unit":"pincée","name":"sel","productSlug":null},{"quantity":40,"unit":"cl","name":"eau tiède","productSlug":null},{"quantity":1,"unit":"l","name":"huile de friture","productSlug":null}]'::jsonb, '[{"text":"Dans un saladier, mélanger la farine, le sucre, la levure, la muscade et le sel.","image":null},{"text":"Verser l''eau tiède peu à peu en mélangeant à la main ou à la spatule jusqu''à obtenir une pâte épaisse, collante et lisse, sans grumeaux.","image":null},{"text":"Couvrir d''un linge et laisser lever 1 heure dans un endroit tiède : la pâte doit doubler de volume et se couvrir de bulles.","image":null},{"text":"Chauffer l''huile à 170 °C. Prendre une poignée de pâte et la presser entre le pouce et l''index pour former une petite boule que l''on fait glisser dans l''huile.","image":null},{"text":"Frire les beignets 3 à 4 minutes en les retournant pour qu''ils dorent uniformément. Égoutter sur du papier absorbant.","image":null},{"text":"Servir tiède, nature ou roulé dans du sucre.","image":null}]'::jsonb, array['Si l''huile est trop chaude, les puff-puff dorent dehors mais restent crus au cœur : baissez le feu.', 'Une cuillère trempée dans l''eau permet aussi de former des boules régulières.']::text[], array['beignets', 'street food', 'goûter']::text[], true, true, '2026-03-03T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000020', 'degue', 'Dégué', 'BF', 'Ouagadougou', 'douceurs', 'Graines de mil cuites à la vapeur, mêlées à un lait caillé sucré et bien frais.', 'Le dégué est un dessert très répandu au Burkina Faso, au Mali, en Côte d''Ivoire et dans toute l''Afrique de l''Ouest sahélienne. Les petites graines de mil roulées, proches du couscous, sont cuites à la vapeur puis mélangées à du lait caillé.

Vendu en sachets bien frais sur les marchés et devant les écoles, il se déguste à toute heure, surtout pendant les journées chaudes. Au Sénégal, un dessert voisin porte le nom de thiakry.', '/recipes/degue.webp', 15, 25, 6, 1, '[{"quantity":250,"unit":"g","name":"couscous de mil","productSlug":"couscous-de-mil"},{"quantity":1,"unit":"l","name":"lait caillé ou yaourt nature brassé","productSlug":null},{"quantity":20,"unit":"cl","name":"lait concentré sucré","productSlug":null},{"quantity":80,"unit":"g","name":"sucre","productSlug":null},{"quantity":1,"unit":"c. à café","name":"extrait de vanille","productSlug":null},{"quantity":1,"unit":"pincée","name":"noix de muscade râpée","productSlug":null},{"quantity":20,"unit":"g","name":"beurre","productSlug":null}]'::jsonb, '[{"text":"Humidifier légèrement le couscous de mil avec 10 cl d''eau froide, bien mélanger du bout des doigts et laisser gonfler 10 minutes.","image":null},{"text":"Cuire le mil 15 minutes à la vapeur dans le haut d''un couscoussier, puis l''égrener dans un grand plat.","image":null},{"text":"Arroser à nouveau de 5 cl d''eau, égrener et remettre à la vapeur 10 minutes. Incorporer le beurre et laisser refroidir complètement.","image":null},{"text":"Fouetter le lait caillé avec le lait concentré, le sucre, la vanille et la muscade jusqu''à obtenir une crème lisse.","image":null},{"text":"Mélanger le mil refroidi à la crème, couvrir et réserver au moins 2 heures au réfrigérateur. Servir très frais dans des bols ou des verres.","image":null}]'::jsonb, array['Ajoutez un peu de lait si le dégué épaissit trop au réfrigérateur : le mil continue d''absorber le liquide.', 'Quelques raisins secs ou un peu de noix de coco râpée apportent une touche gourmande.']::text[], array['mil', 'lait caillé', 'dessert frais']::text[], false, true, '2026-03-04T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000021', 'misir-wat', 'Misir wat', 'ET', 'Addis-Abeba', 'mijotes', 'Lentilles corail fondantes, mijotées dans une sauce rouge au berbéré.', 'Le misir wat est l''un des piliers de la table éthiopienne. Pendant les nombreux jours de jeûne de l''Église orthodoxe éthiopienne, où l''on renonce aux produits animaux, il s''impose comme le plat du quotidien, servi au centre d''une grande injera que l''on partage à la main.

Tout commence par des oignons longuement étuvés sans matière grasse, une technique typique de la cuisine éthiopienne, avant l''arrivée du berbéré, ce mélange d''épices rouge et parfumé qui donne au plat sa couleur profonde et sa chaleur.', '/recipes/misir-wat.webp', 15, 50, 4, 1, '[{"quantity":300,"unit":"g","name":"lentilles corail","productSlug":null},{"quantity":3,"unit":null,"name":"oignons rouges","productSlug":null},{"quantity":4,"unit":"gousses","name":"ail","productSlug":null},{"quantity":1,"unit":"morceau","name":"gingembre frais (3 cm)","productSlug":null},{"quantity":2,"unit":"c. à soupe","name":"berbéré","productSlug":"berbere"},{"quantity":2,"unit":"c. à soupe","name":"concentré de tomate","productSlug":null},{"quantity":6,"unit":"c. à soupe","name":"huile végétale (ou niter kibbeh)","productSlug":null},{"quantity":1,"unit":"l","name":"eau chaude","productSlug":null},{"quantity":null,"unit":null,"name":"sel","productSlug":null}]'::jsonb, '[{"text":"Rincer les lentilles corail à l''eau froide jusqu''à ce que l''eau soit claire, puis les égoutter.","image":null},{"text":"Hacher très finement les oignons (ou les mixer). Les faire cuire à sec dans une cocotte à feu moyen pendant 10 minutes en remuant, jusqu''à ce qu''ils perdent leur eau et commencent à colorer.","image":null},{"text":"Ajouter l''huile, l''ail et le gingembre râpés, puis cuire 5 minutes. Incorporer le berbéré et le concentré de tomate et laisser revenir 3 minutes à feu doux, en ajoutant un filet d''eau si le mélange attache.","image":null},{"text":"Verser les lentilles et l''eau chaude. Porter à frémissement, couvrir à moitié et laisser mijoter 25 à 30 minutes en remuant régulièrement, jusqu''à obtenir une texture fondante et nappante.","image":null},{"text":"Saler, rectifier la consistance avec un peu d''eau si besoin et laisser reposer 5 minutes hors du feu avant de servir.","image":null}]'::jsonb, array['Servez sur une injera, avec du shiro et des légumes sautés pour composer un beyainetu, l''assiette végétarienne éthiopienne.', 'Ajustez la quantité de berbéré selon votre goût : une cuillère pour une version douce, trois pour une version bien relevée.']::text[], array['végétarien', 'lentilles', 'épicé']::text[], true, true, '2026-03-05T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000022', 'shiro', 'Shiro', 'ET', 'Hauts plateaux', 'mijotes', 'Une purée veloutée de farine de pois chiches, relevée au berbéré.', 'Le shiro est présent dans presque tous les foyers d''Éthiopie et d''Érythrée. On le prépare à partir d''une farine de pois chiches ou de fèves grillées, souvent déjà mélangée à des épices, ce qui en fait un plat rapide et économique.

Servi fumant dans un petit plat en terre cuite, le shiro tegabino est une spécialité des restaurants d''Addis-Abeba : il arrive encore bouillonnant à table, accompagné d''injera.', '/recipes/shiro.webp', 10, 30, 4, 1, '[{"quantity":120,"unit":"g","name":"farine de pois chiches","productSlug":null},{"quantity":2,"unit":null,"name":"oignons rouges","productSlug":null},{"quantity":3,"unit":"gousses","name":"ail","productSlug":null},{"quantity":1,"unit":"c. à soupe","name":"berbéré","productSlug":"berbere"},{"quantity":1,"unit":null,"name":"tomate mûre","productSlug":null},{"quantity":5,"unit":"c. à soupe","name":"huile végétale","productSlug":null},{"quantity":75,"unit":"cl","name":"eau","productSlug":null},{"quantity":1,"unit":null,"name":"piment vert","productSlug":null},{"quantity":null,"unit":null,"name":"sel","productSlug":null}]'::jsonb, '[{"text":"Hacher très finement les oignons et les faire suer à sec dans une casserole à feu moyen pendant 8 minutes, en remuant.","image":null},{"text":"Ajouter l''huile, l''ail écrasé et la tomate râpée, puis laisser cuire 5 minutes. Incorporer le berbéré et remuer 2 minutes.","image":null},{"text":"Verser l''eau et porter à frémissement. Ajouter la farine de pois chiches en pluie, en fouettant sans arrêt pour éviter les grumeaux.","image":null},{"text":"Baisser le feu et laisser cuire 15 minutes en remuant souvent : la sauce doit devenir lisse, épaisse et brillante. Rallonger d''un peu d''eau si elle devient trop compacte.","image":null},{"text":"Saler, ajouter le piment vert fendu en deux et servir aussitôt, bien chaud.","image":null}]'::jsonb, array['Pour un shiro plus parfumé, torréfiez légèrement la farine de pois chiches à sec dans une poêle avant de l''utiliser.', 'Une cuillère de beurre clarifié épicé (niter kibbeh) en fin de cuisson lui donne une belle rondeur.']::text[], array['végétarien', 'pois chiches', 'rapide']::text[], false, true, '2026-03-06T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000023', 'injera', 'Injera au teff', 'ET', 'Hauts plateaux', 'accompagnements', 'La grande galette alvéolée et légèrement acidulée qui sert d''assiette et de couverts.', 'L''injera est au cœur du repas éthiopien et érythréen. Préparée à partir de teff, une toute petite céréale cultivée depuis des millénaires sur les hauts plateaux de la Corne de l''Afrique, elle sert à la fois de plateau, de pain et de couverts : on en déchire un morceau pour saisir les sauces.

Sa pâte fermente plusieurs jours, ce qui lui donne son goût acidulé et sa surface criblée de petits trous. On la cuit traditionnellement sur un mitad, une large plaque de terre cuite.', '/recipes/injera.webp', 20, 30, 6, 3, '[{"quantity":500,"unit":"g","name":"farine de teff","productSlug":"farine-de-teff"},{"quantity":75,"unit":"cl","name":"eau tiède non chlorée","productSlug":null},{"quantity":25,"unit":"cl","name":"eau chaude (pour l''absit)","productSlug":null},{"quantity":1,"unit":"pincée","name":"levure boulangère sèche (facultatif)","productSlug":null},{"quantity":1,"unit":"pincée","name":"sel","productSlug":null}]'::jsonb, '[{"text":"Mélanger la farine de teff et l''eau tiède dans un grand saladier en verre pour obtenir une pâte lisse, ajouter la levure si vous en utilisez. Couvrir d''un torchon et laisser fermenter 2 à 3 jours à température ambiante.","image":null},{"text":"La pâte doit se couvrir de bulles et d''une fine couche de liquide sur le dessus, avec une odeur légèrement acide. Retirer ce liquide jaunâtre, puis bien remuer.","image":null},{"text":"Prélever environ 10 cl de pâte et la cuire dans une petite casserole avec l''eau chaude en fouettant 2 à 3 minutes jusqu''à épaississement (c''est l''absit). Laisser tiédir puis l''incorporer au reste de la pâte avec le sel. Laisser reposer 1 heure : la pâte doit avoir la consistance d''une pâte à crêpes un peu fluide.","image":null},{"text":"Chauffer une grande poêle antiadhésive à feu moyen, sans matière grasse. Verser une louche de pâte en spirale, de l''extérieur vers le centre, et incliner légèrement la poêle.","image":null},{"text":"Dès que des trous apparaissent sur toute la surface, couvrir et cuire encore 1 minute : l''injera se cuit d''un seul côté et ne se retourne pas. Elle est prête quand les bords se décollent.","image":null},{"text":"Faire glisser l''injera sur un torchon propre et la laisser refroidir à plat avant d''empiler les suivantes.","image":null}]'::jsonb, array['Si vous débutez, remplacez un tiers du teff par de la farine de blé ou d''orge : la pâte sera plus facile à maîtriser.', 'Gardez 10 cl de pâte fermentée pour lancer la fournée suivante, comme un levain.']::text[], array['teff', 'fermentation', 'galette']::text[], false, true, '2026-03-07T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000024', 'pilau', 'Pilau de Zanzibar', 'TZ', 'Zanzibar', 'riz-cereales', 'Un riz parfumé à la cardamome, au clou de girofle et à la cannelle, cuit avec du bœuf.', 'Sur l''île de Zanzibar, longtemps surnommée l''île aux épices, le pilau raconte des siècles d''échanges dans l''océan Indien entre la côte swahilie, l''Arabie et l''Inde. Clou de girofle, cannelle, cardamome et cumin s''y retrouvent dans un riz doré et fumant.

C''est le plat des fêtes, des mariages et des repas de l''Aïd sur toute la côte swahilie, de Mombasa à Dar es Salaam. On le sert volontiers avec un kachumbari, une salade fraîche de tomates et d''oignons.', '/recipes/pilau.webp', 25, 75, 6, 2, '[{"quantity":500,"unit":"g","name":"riz basmati","productSlug":null},{"quantity":600,"unit":"g","name":"bœuf à braiser en cubes","productSlug":null},{"quantity":3,"unit":null,"name":"oignons","productSlug":null},{"quantity":5,"unit":"gousses","name":"ail","productSlug":null},{"quantity":1,"unit":"morceau","name":"gingembre frais (4 cm)","productSlug":null},{"quantity":2,"unit":null,"name":"pommes de terre","productSlug":null},{"quantity":6,"unit":null,"name":"gousses de cardamome","productSlug":null},{"quantity":6,"unit":null,"name":"clous de girofle","productSlug":null},{"quantity":1,"unit":null,"name":"bâton de cannelle","productSlug":null},{"quantity":2,"unit":"c. à café","name":"graines de cumin","productSlug":null},{"quantity":8,"unit":"c. à soupe","name":"huile végétale","productSlug":null},{"quantity":null,"unit":null,"name":"poivre noir en grains et sel","productSlug":null}]'::jsonb, '[{"text":"Cuire le bœuf dans 1,2 l d''eau salée avec la moitié de l''ail et du gingembre pendant 45 minutes. Réserver la viande et le bouillon séparément.","image":null},{"text":"Rincer le riz jusqu''à ce que l''eau soit claire, puis le laisser tremper 20 minutes et l''égoutter. Concasser grossièrement la cardamome, le clou de girofle, le cumin et une demi-cuillère de poivre au mortier.","image":null},{"text":"Dans une grande cocotte, faire dorer longuement les oignons émincés dans l''huile, 15 minutes environ, jusqu''à ce qu''ils soient bien bruns : c''est ce qui donne sa couleur au pilau.","image":null},{"text":"Ajouter les épices concassées, la cannelle, le reste de l''ail et du gingembre, et faire revenir 2 minutes. Ajouter le bœuf et les pommes de terre en gros cubes, puis remuer 3 minutes.","image":null},{"text":"Verser le riz, bien l''enrober, puis mouiller avec 75 cl de bouillon chaud. Saler, porter à ébullition et laisser cuire à découvert jusqu''à ce que le liquide affleure le riz.","image":null},{"text":"Couvrir hermétiquement, baisser au minimum et laisser cuire 15 minutes sans soulever le couvercle. Laisser reposer 10 minutes hors du feu, puis égrener délicatement à la fourchette.","image":null}]'::jsonb, array['Servez avec un kachumbari : tomates, oignon rouge et piment en fines tranches, jus de citron vert et coriandre.', 'Les oignons doivent être bien caramélisés sans brûler, sinon le riz sera amer.']::text[], array['épices', 'riz', 'fête']::text[], true, true, '2026-03-08T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000025', 'ugali-sukuma-wiki', 'Ugali et sukuma wiki', 'KE', 'Nairobi', 'accompagnements', 'La pâte ferme de maïs blanc et ses feuilles de chou vert sautées à la tomate.', 'L''ugali est l''accompagnement de base au Kenya et dans une grande partie de l''Afrique de l''Est : une pâte ferme de farine de maïs blanc, que l''on roule en boulette dans la main pour attraper sauces et légumes.

Sukuma wiki signifie en swahili « pousser la semaine » : ce plat de chou vert (collard) sauté, bon marché et vite préparé, permettait de tenir jusqu''à la fin de la semaine. Le duo se retrouve aussi bien à la maison que dans les petites cantines de Nairobi.', '/recipes/ugali-sukuma-wiki.webp', 15, 25, 4, 1, '[{"quantity":400,"unit":"g","name":"farine de maïs blanc fine","productSlug":null},{"quantity":1,"unit":"l","name":"eau","productSlug":null},{"quantity":1,"unit":"botte","name":"chou cavalier (collard) ou chou kale","productSlug":null},{"quantity":1,"unit":null,"name":"oignon","productSlug":null},{"quantity":2,"unit":null,"name":"tomates","productSlug":null},{"quantity":2,"unit":"gousses","name":"ail","productSlug":null},{"quantity":3,"unit":"c. à soupe","name":"huile végétale","productSlug":null},{"quantity":1,"unit":null,"name":"cube de bouillon (facultatif)","productSlug":null},{"quantity":null,"unit":null,"name":"sel et poivre de Penja","productSlug":"poivre-de-penja"}]'::jsonb, '[{"text":"Pour le sukuma wiki, retirer les grosses côtes du chou, empiler les feuilles, les rouler et les couper en très fines lanières.","image":null},{"text":"Faire revenir l''oignon émincé dans l''huile 5 minutes, ajouter l''ail puis les tomates coupées en dés et cuire 5 minutes jusqu''à ce qu''elles fondent. Ajouter le chou, le bouillon émietté, saler et poivrer. Cuire 5 à 7 minutes à feu vif en remuant : les feuilles doivent rester vertes et légèrement croquantes.","image":null},{"text":"Pour l''ugali, porter l''eau légèrement salée à ébullition dans une casserole à fond épais. Verser un tiers de la farine en pluie en remuant avec une cuillère en bois pour obtenir une bouillie.","image":null},{"text":"Ajouter le reste de la farine progressivement en écrasant la pâte contre les parois pour éliminer les grumeaux. La pâte devient très ferme et se détache des bords.","image":null},{"text":"Couvrir et laisser cuire 3 minutes à feu doux, retourner la pâte, puis cuire encore 3 minutes. Façonner en dôme avec une cuillère mouillée et démouler sur un plat.","image":null}]'::jsonb, array['Accompagnez d''un nyama choma (viande grillée) ou d''un ragoût de haricots pour un repas complet.', 'Pour manger l''ugali à la kényane, prenez-en une petite boule, creusez-la avec le pouce et servez-vous-en comme d''une cuillère.']::text[], array['maïs', 'légumes verts', 'quotidien']::text[], false, true, '2026-03-09T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000026', 'luwombo', 'Luwombo de poulet', 'UG', 'Buganda', 'mijotes', 'Poulet et sauce à l''arachide cuits à la vapeur dans des feuilles de bananier.', 'Le luwombo est un plat de cérémonie du royaume du Buganda, au centre de l''Ouganda. On raconte qu''il aurait été créé à la fin du XIXe siècle par le cuisinier du kabaka (le roi), et il reste aujourd''hui le plat d''honneur des mariages et des fêtes de famille.

Chaque portion est enveloppée dans des feuilles de bananier assouplies au-dessus du feu, puis cuite longuement à la vapeur. La sauce à l''arachide s''imprègne alors du parfum végétal des feuilles.', '/recipes/luwombo.webp', 45, 90, 4, 3, '[{"quantity":1.2,"unit":"kg","name":"poulet fermier coupé en morceaux","productSlug":null},{"quantity":200,"unit":"g","name":"pâte d''arachide","productSlug":"pate-d-arachide"},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":3,"unit":null,"name":"tomates","productSlug":null},{"quantity":3,"unit":"gousses","name":"ail","productSlug":null},{"quantity":2,"unit":"c. à soupe","name":"huile végétale","productSlug":null},{"quantity":40,"unit":"cl","name":"eau chaude","productSlug":null},{"quantity":4,"unit":null,"name":"grandes feuilles de bananier","productSlug":null},{"quantity":null,"unit":null,"name":"sel et poivre de Penja","productSlug":"poivre-de-penja"}]'::jsonb, '[{"text":"Saler et poivrer le poulet, puis le faire dorer dans l''huile 10 minutes. Réserver. Dans la même cocotte, faire fondre les oignons émincés, l''ail et les tomates en dés pendant 8 minutes.","image":null},{"text":"Délayer la pâte d''arachide dans l''eau chaude jusqu''à obtenir une sauce lisse et nappante, l''ajouter aux tomates et cuire 5 minutes à feu doux en remuant. Saler.","image":null},{"text":"Passer rapidement les feuilles de bananier au-dessus d''une flamme ou les plonger quelques secondes dans l''eau bouillante pour les assouplir. Retirer la nervure centrale et les couper en grands carrés.","image":null},{"text":"Superposer deux carrés en croix, déposer au centre un quart du poulet et de la sauce, puis rabattre les bords pour former une aumônière. Fermer avec une lanière de feuille ou de la ficelle de cuisine.","image":null},{"text":"Déposer les paquets dans un grand faitout sur une grille ou un lit de tiges de bananier, avec 3 cm d''eau au fond. Couvrir et cuire à la vapeur 1 heure 15 en surveillant le niveau d''eau.","image":null},{"text":"Servir chaque convive avec son paquet, que l''on ouvre à table.","image":null}]'::jsonb, array['Accompagnez de matoke (bananes plantain vertes cuites à la vapeur et écrasées) ou de riz.', 'Faute de feuilles de bananier, doublez du papier sulfurisé avec du papier aluminium : le goût sera moins typique, mais la cuisson identique.']::text[], array['arachide', 'vapeur', 'fête']::text[], false, true, '2026-03-10T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000027', 'romazava', 'Romazava', 'MG', 'Hautes Terres, Antananarivo', 'mijotes', 'Le bouillon national malgache de viande et de brèdes, avec les fameuses brèdes mafane.', 'Souvent présenté comme le plat national de Madagascar, le romazava est un bouillon de viande de zébu mijoté avec plusieurs sortes de brèdes, ces feuilles vertes que l''on trouve sur tous les marchés de l''île. Son nom évoquerait un « bouillon clair ».

Sa signature, ce sont les brèdes mafane (cresson de Pará) : leurs petites fleurs jaunes provoquent un léger picotement sur la langue. Le romazava se sert en grande quantité, versé sur un bol de riz blanc, base de tous les repas malgaches.', '/recipes/romazava.webp', 25, 75, 6, 2, '[{"quantity":800,"unit":"g","name":"bœuf (ou zébu) à bouillir, en cubes","productSlug":null},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":3,"unit":null,"name":"tomates","productSlug":null},{"quantity":4,"unit":"gousses","name":"ail","productSlug":null},{"quantity":1,"unit":"morceau","name":"gingembre frais (4 cm)","productSlug":null},{"quantity":1,"unit":"botte","name":"brèdes mafane (ou cresson)","productSlug":null},{"quantity":1,"unit":"botte","name":"brèdes chinoises (pak choï)","productSlug":null},{"quantity":1,"unit":"botte","name":"brèdes morelle ou épinards","productSlug":null},{"quantity":2,"unit":"c. à soupe","name":"huile végétale","productSlug":null},{"quantity":null,"unit":null,"name":"sel et poivre de Penja","productSlug":"poivre-de-penja"}]'::jsonb, '[{"text":"Faire revenir la viande dans l''huile dans un grand faitout 10 minutes, jusqu''à ce qu''elle soit bien colorée.","image":null},{"text":"Ajouter les oignons émincés, puis l''ail et le gingembre pilés ensemble. Cuire 5 minutes avant d''ajouter les tomates coupées en morceaux.","image":null},{"text":"Couvrir d''eau à hauteur (environ 1,5 l), saler et laisser mijoter à couvert 45 minutes, jusqu''à ce que la viande soit tendre.","image":null},{"text":"Laver les brèdes à grande eau, les équeuter et les couper grossièrement. Ajouter d''abord les brèdes chinoises et la morelle, cuire 8 minutes.","image":null},{"text":"Ajouter les brèdes mafane en dernier et cuire encore 5 minutes : elles doivent rester parfumées. Rectifier l''assaisonnement et servir très chaud avec du riz blanc.","image":null}]'::jsonb, array['Le cresson de fontaine ou un mélange cresson et épinards remplace correctement les brèdes mafane, sans leur effet picotant.', 'À Madagascar, on accompagne souvent le romazava d''un sakay, un condiment pimenté, et d''un rougail de tomates.']::text[], array['bouillon', 'brèdes', 'zébu']::text[], false, true, '2026-03-11T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000028', 'ravitoto', 'Ravitoto sy henakisoa', 'MG', 'Hautes Terres', 'mijotes', 'Feuilles de manioc pilées mijotées avec du porc, à l''ail et au gingembre.', 'Ravitoto signifie littéralement « feuilles pilées » en malgache : ce sont des feuilles de manioc écrasées au pilon, puis cuites longuement avec du porc (henakisoa). C''est l''un des plats les plus aimés de Madagascar, que l''on prépare pour le repas dominical ou lorsque la famille est réunie.

Le gras du porc fond dans les feuilles et leur donne une texture riche et soyeuse, relevée par l''ail et le gingembre. Certaines familles y ajoutent du lait de coco, surtout sur la côte est.', '/recipes/ravitoto.webp', 30, 90, 6, 2, '[{"quantity":300,"unit":"g","name":"feuilles de manioc pilées séchées","productSlug":"feuilles-de-manioc"},{"quantity":1,"unit":"kg","name":"poitrine ou échine de porc en cubes","productSlug":null},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":6,"unit":"gousses","name":"ail","productSlug":null},{"quantity":1,"unit":"morceau","name":"gingembre frais (4 cm)","productSlug":null},{"quantity":2,"unit":null,"name":"tomates","productSlug":null},{"quantity":20,"unit":"cl","name":"lait de coco (facultatif)","productSlug":null},{"quantity":null,"unit":null,"name":"sel et poivre de Penja","productSlug":"poivre-de-penja"}]'::jsonb, '[{"text":"Réhydrater les feuilles de manioc 30 minutes dans l''eau tiède, puis les rincer et les égoutter. Les cuire 20 minutes dans une grande casserole d''eau bouillante et jeter l''eau de cuisson.","image":null},{"text":"Mettre le porc dans une cocotte avec un fond d''eau et un peu de sel. Cuire à couvert 20 minutes, puis retirer le couvercle et laisser l''eau s''évaporer jusqu''à ce que la viande dore dans son propre gras.","image":null},{"text":"Ajouter les oignons émincés, puis l''ail et le gingembre pilés. Faire revenir 5 minutes, ajouter les tomates en dés et cuire encore 5 minutes.","image":null},{"text":"Incorporer les feuilles de manioc égouttées, bien mélanger et mouiller avec 50 cl d''eau. Laisser mijoter à couvert 40 minutes à feu doux en remuant de temps en temps.","image":null},{"text":"Ajouter le lait de coco si vous le souhaitez, cuire encore 10 minutes et rectifier l''assaisonnement. Le plat doit être fondant et peu liquide. Servir avec du riz blanc.","image":null}]'::jsonb, array['Les feuilles de manioc doivent toujours être bien cuites : ne raccourcissez pas le temps de cuisson.', 'Comme beaucoup de plats mijotés, le ravitoto est encore meilleur réchauffé le lendemain.']::text[], array['porc', 'feuilles de manioc', 'dimanche']::text[], false, true, '2026-03-12T00:00:00.000Z'),
  ('40000000-0000-4000-a000-000000000029', 'bobotie', 'Bobotie', 'ZA', 'Le Cap', 'mijotes', 'Un hachis de bœuf doucement épicé au curry, fruité, et gratiné sous une crème à l''œuf.', 'Le bobotie est souvent présenté comme le plat national sud-africain. Il est étroitement associé à la cuisine du Cap, et en particulier à la communauté dite Cape Malay, dont les ancêtres venaient d''Asie du Sud-Est et d''Inde. Le mariage des épices, des fruits secs et de la viande hachée témoigne de ce long métissage culinaire.

Sous sa couche dorée d''œufs battus au lait, le hachis parfumé au curry, légèrement sucré par la confiture d''abricot et les raisins secs, se sert avec un riz jaune au curcuma et un chutney de fruits.', '/recipes/bobotie.webp', 25, 60, 6, 2, '[{"quantity":800,"unit":"g","name":"bœuf haché","productSlug":null},{"quantity":2,"unit":null,"name":"oignons","productSlug":null},{"quantity":2,"unit":"gousses","name":"ail","productSlug":null},{"quantity":30,"unit":"g","name":"pain de mie rassis (1 tranche)","productSlug":null},{"quantity":35,"unit":"cl","name":"lait","productSlug":null},{"quantity":2,"unit":"c. à soupe","name":"curry en poudre doux","productSlug":null},{"quantity":1,"unit":"c. à café","name":"curcuma","productSlug":null},{"quantity":2,"unit":"c. à soupe","name":"confiture d''abricot ou chutney","productSlug":null},{"quantity":50,"unit":"g","name":"raisins secs","productSlug":null},{"quantity":1,"unit":"c. à soupe","name":"jus de citron","productSlug":null},{"quantity":3,"unit":null,"name":"œufs","productSlug":null},{"quantity":4,"unit":null,"name":"feuilles de laurier","productSlug":null}]'::jsonb, '[{"text":"Préchauffer le four à 180 °C. Faire tremper le pain dans 10 cl de lait, puis l''essorer en réservant le lait.","image":null},{"text":"Dans une grande poêle, faire fondre les oignons émincés dans un filet d''huile 8 minutes. Ajouter l''ail, le curry et le curcuma, puis remuer 1 minute.","image":null},{"text":"Ajouter la viande hachée et la faire cuire 8 minutes en l''émiettant. Hors du feu, incorporer le pain essoré, la confiture, les raisins secs, le jus de citron et 1 œuf battu. Saler et poivrer.","image":null},{"text":"Tasser le mélange dans un plat à gratin beurré et enfoncer les feuilles de laurier à la surface.","image":null},{"text":"Battre les 2 œufs restants avec le reste du lait et une pincée de sel, puis verser sur la viande.","image":null},{"text":"Enfourner pour 35 à 40 minutes, jusqu''à ce que la crème soit prise et bien dorée. Laisser reposer 5 minutes avant de servir.","image":null}]'::jsonb, array['Servez avec un riz jaune (cuit avec du curcuma, un bâton de cannelle et quelques raisins secs) et un chutney de fruits.', 'Préparez le hachis la veille : les épices auront le temps de se marier.']::text[], array['curry', 'gratin', 'Cape Malay']::text[], true, true, '2026-03-13T00:00:00.000Z'),
  ('40000000-0000-4000-a000-00000000002a', 'chakalaka', 'Chakalaka', 'ZA', 'Gauteng, Johannesburg', 'accompagnements', 'Un condiment pimenté de poivrons, carottes et haricots, compagnon du braai.', 'La chakalaka serait née dans les townships de Johannesburg, où les mineurs auraient cuisiné sur le feu des légumes en conserve, des haricots et du piment pour relever la pâte de maïs. Elle est devenue un incontournable de la table sud-africaine.

On la retrouve à chaque braai, le barbecue sud-africain, à côté des saucisses boerewors et du pap, la bouillie de maïs. Chaque famille a sa recette, plus ou moins piquante.', '/recipes/chakalaka.webp', 15, 30, 6, 1, '[{"quantity":1,"unit":null,"name":"oignon","productSlug":null},{"quantity":1,"unit":null,"name":"poivron rouge","productSlug":null},{"quantity":1,"unit":null,"name":"poivron vert","productSlug":null},{"quantity":3,"unit":null,"name":"carottes","productSlug":null},{"quantity":3,"unit":"gousses","name":"ail","productSlug":null},{"quantity":1,"unit":"morceau","name":"gingembre frais (2 cm)","productSlug":null},{"quantity":2,"unit":null,"name":"piments frais","productSlug":null},{"quantity":1,"unit":"c. à soupe","name":"curry en poudre","productSlug":null},{"quantity":400,"unit":"g","name":"tomates concassées en conserve","productSlug":null},{"quantity":400,"unit":"g","name":"haricots blancs à la sauce tomate (baked beans)","productSlug":null},{"quantity":3,"unit":"c. à soupe","name":"huile végétale","productSlug":null},{"quantity":null,"unit":null,"name":"sel","productSlug":null}]'::jsonb, '[{"text":"Émincer l''oignon, couper les poivrons en petits dés, râper grossièrement les carottes et hacher finement l''ail, le gingembre et les piments.","image":null},{"text":"Faire revenir l''oignon dans l''huile 5 minutes, puis ajouter l''ail, le gingembre, les piments et le curry. Remuer 1 minute jusqu''à ce que les épices embaument.","image":null},{"text":"Ajouter les poivrons et cuire 5 minutes, puis les carottes râpées et cuire encore 3 minutes.","image":null},{"text":"Verser les tomates concassées, saler et laisser mijoter 10 minutes à feu doux.","image":null},{"text":"Incorporer les haricots avec leur sauce et laisser cuire encore 5 minutes. Servir chaud ou à température ambiante.","image":null}]'::jsonb, array['La chakalaka se garde plusieurs jours au réfrigérateur et se sert aussi froide, comme une relish.', 'Pour une version plus douce, retirez les graines des piments ou n''en mettez qu''un seul.']::text[], array['braai', 'légumes', 'épicé']::text[], false, true, '2026-03-14T00:00:00.000Z'),
  ('40000000-0000-4000-a000-00000000002b', 'cafe-touba', 'Café Touba', 'SN', 'Diourbel, Touba', 'douceurs', 'Café torréfié maison avec le djar, poivre de Selim aux notes boisées et poivrées.', 'Le café Touba porte le nom de la ville sainte fondée par Cheikh Ahmadou Bamba, figure de la confrérie mouride. Selon la tradition, c''est dans l''entourage du cheikh que l''habitude de parfumer le café au djar s''est installée, avant de gagner tout le Sénégal.

Aujourd''hui, on le boit à toute heure, servi brûlant et bien sucré dans de petits gobelets, au coin des rues de Dakar comme lors du grand Magal de Touba. Son goût se reconnaît immédiatement : une amertume ronde, relevée par le parfum résineux et légèrement piquant du poivre de Selim.', '/recipes/cafe-touba.webp', 10, 25, 10, 2, '[{"quantity":250,"unit":"g","name":"café vert (robusta de préférence)","productSlug":null},{"quantity":15,"unit":"g","name":"poivre de Selim (djar) en gousses","productSlug":"poivre-de-selim"},{"quantity":2,"unit":null,"name":"clous de girofle (facultatif)","productSlug":null},{"quantity":1,"unit":"l","name":"eau","productSlug":null},{"quantity":120,"unit":"g","name":"sucre","productSlug":null}]'::jsonb, '[{"text":"Faire chauffer une grande poêle épaisse à sec sur feu moyen, puis y verser le café vert. Le remuer sans arrêt avec une cuillère en bois pendant 15 à 20 minutes, jusqu''à ce que les grains deviennent brun foncé et commencent à craquer.","image":null},{"text":"Ajouter les gousses de djar et les clous de girofle, puis poursuivre la torréfaction 3 à 4 minutes en remuant : les épices doivent griller sans noircir et libérer leur parfum.","image":null},{"text":"Étaler le mélange sur un plateau et le laisser refroidir complètement, puis le moudre finement au moulin à café ou au pilon.","image":null},{"text":"Porter l''eau à frémissement. Placer 6 à 7 c. à soupe de mouture dans un filtre en tissu ou en papier, puis verser l''eau chaude lentement par-dessus.","image":null},{"text":"Sucrer le café recueilli et le repasser une seconde fois dans le filtre pour qu''il gagne en corps. Servir très chaud dans de petits verres.","image":null}]'::jsonb, array['Conservez la mouture dans un bocal hermétique à l''abri de la lumière : elle garde son parfum plusieurs semaines.', 'Pour une version plus douce, réduisez le djar à 10 g ; pour un café plus poivré, montez jusqu''à 20 g.']::text[], array['café', 'épices', 'tradition']::text[], true, true, '2026-03-15T00:00:00.000Z'),
  ('40000000-0000-4000-a000-00000000002c', 'jus-de-gingembre', 'Jus de gingembre (gnamankoudji)', 'CI', 'Abidjan', 'douceurs', 'Boisson glacée au gingembre frais, citron et ananas, vive et piquante.', 'En Côte d''Ivoire, le gnamankoudji est de toutes les fêtes : mariages, baptêmes, anniversaires et soirées de maquis. Vendu en petites bouteilles bien fraîches au bord des routes, il fait partie du paysage d''Abidjan.

Chaque famille a sa recette : certains y ajoutent de l''ananas, d''autres de la menthe ou de la vanille. Le principe reste le même, un gingembre généreux dont le piquant est adouci par le sucre et l''acidité du citron.', '/recipes/jus-de-gingembre.webp', 25, 0, 8, 1, '[{"quantity":300,"unit":"g","name":"gingembre frais","productSlug":null},{"quantity":0.5,"unit":null,"name":"ananas bien mûr","productSlug":null},{"quantity":3,"unit":null,"name":"citrons verts","productSlug":null},{"quantity":200,"unit":"g","name":"sucre","productSlug":null},{"quantity":1,"unit":null,"name":"sachet de sucre vanillé","productSlug":null},{"quantity":5,"unit":null,"name":"feuilles de menthe fraîche (facultatif)","productSlug":null},{"quantity":2,"unit":"l","name":"eau froide","productSlug":null}]'::jsonb, '[{"text":"Peler le gingembre à la cuillère, puis le couper en rondelles. Peler l''ananas, retirer le cœur et le couper en morceaux.","image":null},{"text":"Mixer le gingembre et l''ananas avec 50 cl d''eau jusqu''à obtenir une purée très fine.","image":null},{"text":"Verser la purée dans un linge propre ou un tamis fin au-dessus d''un saladier, ajouter le reste de l''eau et presser fortement pour extraire tout le jus.","image":null},{"text":"Ajouter le jus des citrons, le sucre, le sucre vanillé et les feuilles de menthe froissées. Mélanger jusqu''à dissolution complète du sucre, puis goûter et ajuster.","image":null},{"text":"Mettre en bouteilles et placer au réfrigérateur au moins 2 heures. Servir très frais, en secouant avant de verser.","image":null}]'::jsonb, array['Le jus se garde 3 jours au frais ; il devient plus piquant avec le temps.', 'Pour un goût plus doux, remplacez une partie du sucre par du miel ou allongez avec un peu plus d''eau.']::text[], array['boisson', 'gingembre', 'fête']::text[], false, true, '2026-03-16T00:00:00.000Z'),
  ('40000000-0000-4000-a000-00000000002d', 'ngalakh', 'Ngalakh', 'SN', 'Dakar et Petite-Côte', 'douceurs', 'Le dessert de Pâques sénégalais : mil, pâte d''arachide et pain de singe.', 'Le ngalakh est la douceur emblématique de Pâques chez les chrétiens du Sénégal. Le Vendredi saint, les familles en préparent de grandes bassines, puis en offrent des bols à leurs voisins, amis et proches, quelle que soit leur religion.

Ce partage est devenu un symbole apprécié de la convivialité sénégalaise. La recette associe trois saveurs du terroir : le mil, l''arachide et le pain de singe, le fruit du baobab, dont l''acidité légère équilibre la richesse de la crème.', '/recipes/ngalakh.webp', 30, 30, 8, 2, '[{"quantity":500,"unit":"g","name":"couscous de mil (sankhal ou arraw)","productSlug":"couscous-de-mil"},{"quantity":250,"unit":"g","name":"pâte d''arachide","productSlug":"pate-d-arachide"},{"quantity":150,"unit":"g","name":"poudre de pain de singe (bouye)","productSlug":"poudre-de-baobab"},{"quantity":200,"unit":"g","name":"sucre","productSlug":null},{"quantity":1.5,"unit":"l","name":"eau","productSlug":null},{"quantity":2,"unit":null,"name":"sachets de sucre vanillé","productSlug":null},{"quantity":1,"unit":"c. à soupe","name":"eau de fleur d''oranger","productSlug":null},{"quantity":1,"unit":"pincée","name":"noix de muscade râpée","productSlug":null},{"quantity":80,"unit":"g","name":"raisins secs","productSlug":null}]'::jsonb, '[{"text":"Humidifier le couscous de mil avec un peu d''eau, l''égrainer à la main, puis le cuire 20 minutes à la vapeur dans un couscoussier. L''égrainer de nouveau et le laisser refroidir.","image":null},{"text":"Dans une casserole, délayer la pâte d''arachide dans 75 cl d''eau chaude avec le sucre. Porter à frémissement et cuire 10 minutes à feu doux en remuant, jusqu''à obtenir une crème lisse. Laisser refroidir.","image":null},{"text":"Délayer la poudre de pain de singe dans 75 cl d''eau froide, puis filtrer au tamis pour retirer les fibres et les éventuels grains.","image":null},{"text":"Mélanger la crème d''arachide refroidie avec le jus de pain de singe, le sucre vanillé, la fleur d''oranger et la muscade. La préparation doit être onctueuse et bien nappante.","image":null},{"text":"Verser cette crème sur le mil, ajouter les raisins secs et mélanger délicatement. Réserver au moins 2 heures au réfrigérateur et servir bien frais.","image":null}]'::jsonb, array['Ne faites jamais cuire le pain de singe : il perdrait son acidité fraîche.', 'Si la crème épaissit trop au froid, détendez-la avec un peu d''eau ou de lait juste avant de servir.']::text[], array['Pâques', 'mil', 'arachide', 'partage']::text[], false, true, '2026-03-17T00:00:00.000Z'),
  ('40000000-0000-4000-a000-00000000002e', 'jus-de-bouye', 'Jus de bouye', 'SN', 'Dakar', 'douceurs', 'Boisson crémeuse et acidulée au pain de singe, le fruit du baobab.', 'Le baobab est l''arbre emblème du Sénégal, présent jusque sur les armoiries du pays. Son fruit, appelé pain de singe, renferme une pulpe blanche et farineuse que l''on nomme bouye en wolof.

Délayée dans l''eau et sucrée, elle donne une boisson onctueuse au goût acidulé, que l''on sert lors des cérémonies familiales, des baptêmes et, pendant le ramadan, à la rupture du jeûne. Souvent enrichi de lait, parfumé à la vanille ou à la fleur d''oranger, le jus de bouye est l''un des grands classiques des tables sénégalaises.', '/recipes/jus-de-bouye.webp', 20, 0, 8, 1, '[{"quantity":200,"unit":"g","name":"poudre de pain de singe (bouye)","productSlug":"poudre-de-baobab"},{"quantity":1.5,"unit":"l","name":"eau froide","productSlug":null},{"quantity":150,"unit":"g","name":"sucre","productSlug":null},{"quantity":20,"unit":"cl","name":"lait concentré sucré (facultatif)","productSlug":null},{"quantity":1,"unit":null,"name":"sachet de sucre vanillé","productSlug":null},{"quantity":1,"unit":"c. à café","name":"eau de fleur d''oranger","productSlug":null}]'::jsonb, '[{"text":"Verser la poudre de pain de singe dans un grand saladier et ajouter progressivement 1 l d''eau froide en fouettant pour éviter les grumeaux.","image":null},{"text":"Laisser reposer 10 minutes, puis malaxer à la main ou au fouet pour bien détacher la pulpe.","image":null},{"text":"Filtrer au tamis fin ou à travers un linge en pressant, afin d''éliminer les fibres et les éventuels grains.","image":null},{"text":"Ajouter le reste de l''eau, le sucre, le sucre vanillé, la fleur d''oranger et le lait concentré. Mélanger jusqu''à dissolution complète et goûter pour ajuster la douceur.","image":null},{"text":"Mettre en bouteilles et réserver au moins 2 heures au réfrigérateur. Bien secouer avant de servir très frais.","image":null}]'::jsonb, array['Sans lait, le jus est plus léger et plus acidulé ; avec lait, il devient crémeux, presque comme un milkshake.', 'Consommez-le dans les 48 heures, gardé au frais.']::text[], array['boisson', 'baobab', 'ramadan']::text[], false, true, '2026-03-18T00:00:00.000Z')
